function buildMenuSpreads(pages) {
  if (!pages || pages.length === 0) return [];
  if (pages.length === 1) return [[pages[0]]];
  const spreads = [[pages[0]]];
  for (let i = 1; i < pages.length; i += 2) {
    spreads.push(pages.slice(i, i + 2));
  }
  return spreads;
}

