const DECK_CATEGORY_ORDER = ["creative-direction", "editorial", "ugc"];
const ALL_PROJECTS = DECK_CATEGORY_ORDER.flatMap((catKey) => {
  const cat = PAPER_CATEGORIES.find((c) => c.key === catKey);
  return (PROJECTS[catKey] || []).map((p) => ({
    ...p,
    categoryLabel: cat ? cat.label : catKey,
  }));
});

// "Spy terminal" text reveal: cycles random glyphs through each character
// before it locks in, left to right — like a decoder guessing a code.
const SCRAMBLE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
function scrambleFrame(text, revealCount) {
  let out = "";
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === " " || i < revealCount) {
      out += ch;
    } else {
      out += SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)];
    }
  }
  return out;
}
function ScrambleText({ text, play, delay = 0, speed = 28 }) {
  const [display, setDisplay] = useState(text);

  useEffect(() => {
    if (!play) {
      setDisplay(text);
      return;
    }
    // show fully-scrambled glyphs right away, even while waiting out `delay`
    setDisplay(scrambleFrame(text, 0));
    let frame = 0;
    let intervalId = null;
    const revealEvery = 2; // frames per character locked in
    const tick = () => {
      frame++;
      const revealCount = Math.floor(frame / revealEvery);
      setDisplay(scrambleFrame(text, revealCount));
      if (revealCount >= text.length) {
        clearInterval(intervalId);
      }
    };
    const startId = setTimeout(() => {
      intervalId = setInterval(tick, speed);
    }, delay);
    return () => {
      clearTimeout(startId);
      if (intervalId) clearInterval(intervalId);
    };
  }, [play, text, delay, speed]);

  return display;
}

const WELCOME_DOLL_IMG = "data:image/webp;base64,";

// Texto que se "escribe" con el mismo efecto de dígitos/letras que se van
// descubriendo (ventana de glifos aleatorios delante del cursor).
function TypeScramble({ text: rawText, play, delay = 0, cps = 75, onDone }) {
  // Soporta **negritas**: se quitan las marcas y se guardan los rangos.
  const parsed = useMemo(() => {
    let plain = "";
    const ranges = [];
    const parts = rawText.split("**");
    parts.forEach((part, idx) => {
      if (idx % 2 === 1) ranges.push([plain.length, plain.length + part.length]);
      plain += part;
    });
    return { plain, ranges };
  }, [rawText]);
  const text = parsed.plain;
  const [n, setN] = useState(0);
  const [, setTick] = useState(0);
  const doneRef = useRef(onDone);
  doneRef.current = onDone;
  useEffect(() => {
    setN(0);
    if (!play) return undefined;
    let id = null;
    const t0 = { v: 0 };
    const start = setTimeout(() => {
      t0.v = performance.now();
      id = setInterval(() => {
        const pos = Math.min(text.length, Math.floor(((performance.now() - t0.v) / 1000) * cps));
        setN(pos);
        setTick((x) => x + 1);
        if (pos >= text.length) {
          clearInterval(id);
          if (doneRef.current) doneRef.current();
        }
      }, 33);
    }, delay);
    return () => {
      clearTimeout(start);
      if (id) clearInterval(id);
    };
  }, [play, text, delay, cps]);
  const WIN = 7;
  const aheadStr = text
    .slice(n, n + WIN)
    .split("")
    .map((ch) => (/\s/.test(ch) ? ch : SCRAMBLE_CHARS[Math.floor(Math.random() * SCRAMBLE_CHARS.length)]))
    .join("");
  // Parte el trozo [from, from+str.length) en segmentos normales / en negritas.
  const segs = (str, from, wrapStyle, cls) => {
    const out = [];
    let buf = "";
    let bold = null;
    for (let k = 0; k < str.length; k++) {
      const isB = parsed.ranges.some(([a, b]) => from + k >= a && from + k < b);
      if (bold === null) bold = isB;
      if (isB !== bold) {
        out.push([buf, bold]);
        buf = "";
        bold = isB;
      }
      buf += str[k];
    }
    if (buf) out.push([buf, bold]);
    return out.map(([txt, b], idx) => {
      const el = b ? <strong>{txt}</strong> : txt;
      return cls || wrapStyle ? <span key={idx} className={cls} style={wrapStyle}>{el}</span> : <Fragment key={idx}>{el}</Fragment>;
    });
  };
  return (
    <>
      {segs(text.slice(0, n), 0)}
      {segs(aheadStr, n, undefined, "welcome-scr")}
      {segs(text.slice(n + WIN), n + WIN, { visibility: "hidden" })}
    </>
  );
}

// Sonido de notificación sintetizado (dos notas suaves). Si el navegador bloquea
// el audio antes de la primera interacción, suena en cuanto la persona toca algo.
function playChimeWebAudio() {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = playChimeWebAudio.ctx || (playChimeWebAudio.ctx = new AC());
    const schedule = () => {
      const t = ctx.currentTime + 0.02;
      [[880, 0], [1318.5, 0.14]].forEach(([f, off]) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = "sine";
        o.frequency.value = f;
        g.gain.setValueAtTime(0.0001, t + off);
        g.gain.exponentialRampToValueAtTime(0.18, t + off + 0.015);
        g.gain.exponentialRampToValueAtTime(0.0001, t + off + 0.7);
        o.connect(g);
        g.connect(ctx.destination);
        o.start(t + off);
        o.stop(t + off + 0.75);
      });
    };
    if (ctx.state === "running") {
      schedule();
    } else {
      const go = () => {
        ctx.resume().then(schedule).catch(() => {});
        ["pointerdown", "keydown", "touchstart"].forEach((ev) => window.removeEventListener(ev, go, true));
      };
      ["pointerdown", "keydown", "touchstart"].forEach((ev) => window.addEventListener(ev, go, true));
      ctx.resume().then(() => { if (ctx.state === "running") { ["pointerdown", "keydown", "touchstart"].forEach((ev) => window.removeEventListener(ev, go, true)); schedule(); } }).catch(() => {});
    }
  } catch (e) {}
}

// WAV de la notificación generado en código (dos notas). Se reproduce con un
// elemento <audio>: en iPhone el audio web ignora el modo silencio solo así.
function makeChimeUrl() {
  const sr = 22050, dur = 0.95, n = Math.floor(sr * dur);
  const buf = new ArrayBuffer(44 + n * 2);
  const v = new DataView(buf);
  const w = (o, str) => { for (let i = 0; i < str.length; i++) v.setUint8(o + i, str.charCodeAt(i)); };
  w(0, "RIFF"); v.setUint32(4, 36 + n * 2, true); w(8, "WAVE"); w(12, "fmt ");
  v.setUint32(16, 16, true); v.setUint16(20, 1, true); v.setUint16(22, 1, true);
  v.setUint32(24, sr, true); v.setUint32(28, sr * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true);
  w(36, "data"); v.setUint32(40, n * 2, true);
  const notes = [[880, 0], [1318.5, 0.14]];
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    let x = 0;
    for (const [f, off] of notes) {
      const k = t - off;
      if (k < 0) continue;
      const env = Math.min(1, k / 0.015) * Math.exp(-k * 6.5);
      x += Math.sin(2 * Math.PI * f * k) * env * 0.42;
    }
    v.setInt16(44 + i * 2, Math.max(-1, Math.min(1, x)) * 32767, true);
  }
  return URL.createObjectURL(new Blob([buf], { type: "audio/wav" }));
}
function playNotifChime() {
  try {
    if (!playNotifChime.el) {
      const el = new Audio(makeChimeUrl());
      el.preload = "auto";
      playNotifChime.el = el;
    }
    const el = playNotifChime.el;
    el.currentTime = 0;
    const pr = el.play();
    if (pr && pr.catch) pr.catch(() => playChimeWebAudio());
  } catch (e) {
    playChimeWebAudio();
  }
}

