const IS_TOUCH = typeof window !== "undefined" && !!window.matchMedia && window.matchMedia("(hover: none)").matches;
function useNarrow() {
  const q = "(max-width: 640px)";
  const [n, setN] = useState(() => typeof window !== "undefined" && !!window.matchMedia && window.matchMedia(q).matches);
  useEffect(() => {
    if (!window.matchMedia) return;
    const m = window.matchMedia(q);
    const on = () => setN(m.matches);
    on();
    if (m.addEventListener) m.addEventListener("change", on); else m.addListener(on);
    return () => { if (m.removeEventListener) m.removeEventListener("change", on); else m.removeListener(on); };
  }, []);
  return n;
}

// Mazo de tarjetas apiladas: la de enfrente se ve completa, las siguientes
// asoman detrás. Mientras el cursor está encima, van "hojeándose" solas en
// el orden del arreglo "items"; con click se abre la que está al frente.
// Se usa tanto para las carpetas de video del USB como para "menús" en
// Diseño de menú.
function HoverCardStack({ items, lang, onOpen, emptyImageLabel }) {
  const narrow = useNarrow();
  const [front, setFront] = useState(0);
  const lastPos = useRef(null);
  const accum = useRef(0);
  const ADVANCE_PX = 46;

  useEffect(() => {
    setFront(0);
  }, [items]);

  if (!items.length) return null;
  const maxLayers = Math.min(items.length, 5);

  const handleMouseEnter = (e) => {
    lastPos.current = { x: e.clientX, y: e.clientY };
    accum.current = 0;
  };

  const handleMouseLeave = () => {
    lastPos.current = null;
    accum.current = 0;
  };

  const handleMouseMove = (e) => {
    if (!lastPos.current || items.length < 2) return;
    const dx = e.clientX - lastPos.current.x;
    const dy = e.clientY - lastPos.current.y;
    lastPos.current = { x: e.clientX, y: e.clientY };
    accum.current += dx + dy * 0.6;
    while (accum.current >= ADVANCE_PX) {
      accum.current -= ADVANCE_PX;
      setFront((f) => (f + 1) % items.length);
    }
    while (accum.current <= -ADVANCE_PX) {
      accum.current += ADVANCE_PX;
      setFront((f) => (f - 1 + items.length) % items.length);
    }
  };

  const handleTouchStart = (e) => {
    const t0 = e.touches[0];
    lastPos.current = { x: t0.clientX, y: t0.clientY };
    accum.current = 0;
  };
  const handleTouchMove = (e) => {
    if (!lastPos.current || items.length < 2) return;
    const x = e.touches[0].clientX;
    const dx = x - lastPos.current.x;
    lastPos.current = { x, y: e.touches[0].clientY };
    accum.current += dx * 1.3;
    while (accum.current >= ADVANCE_PX) {
      accum.current -= ADVANCE_PX;
      setFront((f) => (f + 1) % items.length);
    }
    while (accum.current <= -ADVANCE_PX) {
      accum.current += ADVANCE_PX;
      setFront((f) => (f - 1 + items.length) % items.length);
    }
  };

  return (
    <div className="card-stack-wrap">
      <div
        className="card-stack card-stack-fan"
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onMouseMove={handleMouseMove}
      >
        {Array.from({ length: maxLayers }).map((_, layer) => {
          const depth = maxLayers - 1 - layer; // 0 = front-most of the rendered layers
          const idx = (front + depth) % items.length;
          const item = items[idx];
          const img = item.thumb || item.img || null;
          return (
            <button
              key={`${idx}-${item.title ? item.title.en : idx}`}
              className="card-stack-item"
              style={{
                zIndex: 10 + layer,
                transform: `translate(${depth * (narrow ? 13 : 26)}px, ${depth * (narrow ? 13 : 20)}px) rotate(${depth * 3.2}deg) scale(${1 - depth * 0.05})`,
              }}
              onClick={() => {
                setFront(idx);
                onOpen(idx);
              }}
              aria-label={item.title ? item.title[lang] : ""}
            >
              {img ? (
                <img src={img} alt="" />
              ) : (
                <div className="card-stack-fallback">{emptyImageLabel}</div>
              )}
              <div className="card-stack-label-row">
                <span className="card-stack-label">{item.title ? item.title[lang] : ""}</span>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

// Carga el video completo como "blob" antes de reproducirlo: así funciona igual
// en Safari, Chrome y la app (Safari no reproduce mp4 si el servidor no soporta
// descarga por rangos, y se queda en 0:00).
function BlobVideo({ src, poster }) {
  const [url, setUrl] = useState(null);
  const [failed, setFailed] = useState(false);
  const [pct, setPct] = useState(0);
  useEffect(() => {
    let dead = false;
    let obj = null;
    const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
    setUrl(null);
    setFailed(false);
    setPct(0);
    (async () => {
      try {
        const r = await fetch(src, ctrl ? { signal: ctrl.signal } : undefined);
        if (!r.ok) throw new Error("http " + r.status);
        const total = Number(r.headers.get("content-length")) || 0;
        let blob;
        if (r.body && r.body.getReader && total) {
          const reader = r.body.getReader();
          const chunks = [];
          let got = 0;
          for (;;) {
            const { done, value } = await reader.read();
            if (done) break;
            chunks.push(value);
            got += value.length;
            if (!dead) setPct(Math.min(99, Math.round((got / total) * 100)));
          }
          blob = new Blob(chunks, { type: "video/mp4" });
        } else {
          const raw = await r.blob();
          blob = new Blob([raw], { type: "video/mp4" });
        }
        if (dead) return;
        obj = URL.createObjectURL(blob);
        setUrl(obj);
      } catch (e) {
        if (!dead) setFailed(true);
      }
    })();
    return () => {
      dead = true;
      if (ctrl) ctrl.abort();
      if (obj) URL.revokeObjectURL(obj);
    };
  }, [src]);

  if (failed) return <video src={src} poster={poster} controls autoPlay playsInline />;
  if (!url) {
    return (
      <div className="usb-video-loading" style={poster ? { backgroundImage: `url(${poster})` } : undefined}>
        <div className="usb-video-loading-veil">
          <span className="usb-video-spinner" />
          <span className="usb-video-loading-pct">{pct > 0 ? `${pct}%` : ""}</span>
        </div>
      </div>
    );
  }
  return <video className="usb-video-ready" src={url} poster={poster} controls autoPlay playsInline />;
}

// Escena de menú: fondo con foto + libro abierto. Un click pasa a la siguiente página.
function MenuScene({ book, lang, showCue }) {
  const narrow = useNarrow();
  const spreads = narrow ? book.pages.map((pg) => [pg]) : buildMenuSpreads(book.pages);
  const total = spreads.length;
  const [page, setPage] = useState(0);
  const [zoom, setZoom] = useState(false);
  const safePage = Math.min(page, Math.max(total - 1, 0));
  const current = spreads[safePage] || [];
  const next = () => {
    if (total > 1) setPage((p) => (p + 1) % total);
  };

  return (
    <section className="menu-scene">
      <div className="menu-book-scrim" />
      <div className="menu-book-topbar">
        <span className="menu-book-spacer" />
        <div className="menu-book-heading">{book.title[lang]}</div>
        <button
          type="button"
          className="menu-book-round-btn"
          onClick={() => setZoom((z) => !z)}
          aria-label={lang === "en" ? "Expand" : "Ampliar"}
        >
          {zoom ? (
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
              <path d="M9 3H3v6M15 3h6v6M9 21H3v-6M15 21h6v-6" />
            </svg>
          ) : (
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
              <path d="M3 9V3h6M15 3h6v6M21 15v6h-6M9 21H3v-6" />
            </svg>
          )}
        </button>
      </div>

      <div
        className={`menu-book-spread ${zoom ? "zoomed" : ""} ${total > 1 ? "flippable" : ""} ${current.length > 1 ? "two-page" : "one-page"}`}
        onClick={next}
        role={total > 1 ? "button" : undefined}
        tabIndex={total > 1 ? 0 : undefined}
        onKeyDown={(e) => { if (total > 1 && (e.key === "Enter" || e.key === " " || e.key === "ArrowRight")) { e.preventDefault(); next(); } }}
      >
        {current.map((src, idx) => (
          <div className="menu-book-page" key={`${safePage}-${idx}`}>
            <img src={src} alt="" draggable={false} />
          </div>
        ))}
      </div>

      {total > 1 && (
        <div className="menu-book-dots">
          {spreads.map((_, i) => (
            <span key={i} className={`menu-book-dot ${i === safePage ? "active" : ""}`} />
          ))}
        </div>
      )}

      {total > 1 && <div className="menu-book-hint">{TRANSLATIONS.turnPagesHint[lang]}</div>}
      {showCue && (
        <div className="menu-scroll-cue" aria-hidden="true">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4">
            <path d="M6 9l6 6 6-6" />
          </svg>
        </div>
      )}
    </section>
  );
}

export default function PortfolioBoard() {
  const [active, setActive] = useState(null); // 'bio' | 'tools' | null
  const [loaded, setLoaded] = useState(false);
  const [contactForm, setContactForm] = useState({ name: "", contact: "", message: "" });
  const [contactSent, setContactSent] = useState(false);
  const [contactSending, setContactSending] = useState(false);
  const [contactError, setContactError] = useState(false);
  const handleContactSubmit = useCallback(async (e) => {
    e.preventDefault();
    if (contactSending) return;
    setContactSending(true);
    setContactError(false);
    try {
      const payload = {
        name: contactForm.name,
        contact: contactForm.contact,
        message: contactForm.message,
        _subject: "Nuevo mensaje desde tu portafolio",
        _template: "table",
        _captcha: "false",
      };
      if (/@/.test(contactForm.contact)) payload.email = contactForm.contact;
      const res = await fetch("https://formsubmit.co/ajax/" + CONTACT_EMAIL, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify(payload),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || String(data.success) === "false") throw new Error("send failed");
      setContactSent(true);
    } catch (err) {
      setContactError(true);
    } finally {
      setContactSending(false);
    }
  }, [contactForm, contactSending]);
  const [cardOpen, setCardOpen] = useState(false);
  const [cardFlipped, setCardFlipped] = useState(false);
  const [cardShine, setCardShine] = useState({ x: 50, y: 50, active: false });
  const [idCardOpen, setIdCardOpen] = useState(false);
  const [idCardShine, setIdCardShine] = useState({ x: 50, y: 50, active: false });
  const [playerOpen, setPlayerOpen] = useState(false);
  const [playerReveal, setPlayerReveal] = useState(false);
  const [usbOpen, setUsbOpen] = useState(false);
  const [usbReveal, setUsbReveal] = useState(false);
  const [activeVideo, setActiveVideo] = useState(null);
  const [activeFolder, setActiveFolder] = useState(null);
  const [activeMenuFolder, setActiveMenuFolder] = useState(null);
  const [usbMin, setUsbMin] = useState(false);
  const [welcomeOpen, setWelcomeOpen] = useState(false);
  const [welcomeStep, setWelcomeStep] = useState(-1);
  const [usbMax, setUsbMax] = useState(false);
  // Vibración "checklist": solo vibra el siguiente elemento sin visitar, en
  // el orden ipod -> presentation card -> usb -> docs de dirección creativa
  // -> tarjeta de contacto. Al abrirlo se marca como visitado y empieza a
  // vibrar el siguiente (el post-it de contacto nunca vibra).
  const [buzzVisited, setBuzzVisited] = useState(() => new Set());
  const nextBuzzStep = [1, 2, 3, 4, 5].find((n) => !buzzVisited.has(n));
  const markBuzzVisited = (n) => {
    setBuzzVisited((prev) => {
      if (prev.has(n)) return prev;
      const next = new Set(prev);
      next.add(n);
      return next;
    });
  };
  const [usbCategory, setUsbCategory] = useState("video");
  const [papersOpen, setPapersOpen] = useState(false);
  const [papersReveal, setPapersReveal] = useState(false);
  const [papersCategory, setPapersCategory] = useState("editorial");
  const [deckOrder, setDeckOrder] = useState(() => ALL_PROJECTS.map((_, i) => i));
  const [moreProject, setMoreProject] = useState(null);
  const advanceDeck = useCallback(() => {
    setDeckOrder((prev) => (prev.length > 1 ? [...prev.slice(1), prev[0]] : prev));
  }, []);

  const [lang, setLang] = useState(() => {
    try {
      const saved = window.localStorage.getItem("portfolio-lang");
      if (saved === "en" || saved === "es") return saved;
    } catch (e) {}
    return "en";
  });
  useEffect(() => {
    try {
      window.localStorage.setItem("portfolio-lang", lang);
    } catch (e) {}
  }, [lang]);
  const t = useCallback((key) => (TRANSLATIONS[key] ? TRANSLATIONS[key][lang] : key), [lang]);

  // Reemplaza esta lista con tus canciones reales: { title, artist, src }
  // src debe ser una URL a un archivo de audio (mp3/m4a) que subas al proyecto.
  const PLAYLIST = [
    { title: "No Ponga Excusas", artist: "Cris MJ", src: "./audio/cris-mj-no-ponga-excusas.mp3" },
    { title: "In Your Arms", artist: "Shift K3Y", src: "./audio/shift-k3y-in-your-arms.mp3" },
    { title: "Thank You", artist: "Dido", src: "./audio/dido-thank-you.mp3" },
  ];

  const [trackIndex, setTrackIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const audioRef = useRef(null);
  const autoAdvanceRef = useRef(false);
  const currentTrack = PLAYLIST[trackIndex] || null;

  useEffect(() => {
    const t = setTimeout(() => setLoaded(true), 80);
    return () => clearTimeout(t);
  }, []);

  // Ventana de bienvenida: al entrar suena una notificación y se abre sola.
  // Los navegadores no dejan sonar audio hasta que la persona hace click, así que
  // una pantalla de entrada desbloquea el audio: el sonido y la ventana salen juntos.
  const [entered, setEntered] = useState(false);
  const enterSite = useCallback(() => {
    setEntered(true);
    playNotifChime();
    setWelcomeOpen(true);
  }, []);
  useEffect(() => {
    if (!welcomeOpen) return;
    setWelcomeStep(-1);
  }, [welcomeOpen, lang]);

  const close = useCallback(() => {
    setActive(null);
    setContactSent(false);
    setContactForm({ name: "", contact: "", message: "" });
  }, []);

  useEffect(() => {
    if (!cardOpen) return;
    setCardFlipped(false);
    const t = setTimeout(() => setCardFlipped(true), 550);
    return () => clearTimeout(t);
  }, [cardOpen]);

  useEffect(() => {
    if (!idCardOpen) setIdCardShine({ x: 50, y: 50, active: false });
  }, [idCardOpen]);

  useEffect(() => {
    if (!cardOpen) setCardShine({ x: 50, y: 50, active: false });
  }, [cardOpen]);

  useEffect(() => {
    if (!playerOpen) return;
    setPlayerReveal(false);
    const t = setTimeout(() => setPlayerReveal(true), 450);
    return () => clearTimeout(t);
  }, [playerOpen]);

  useEffect(() => {
    if (!usbOpen) return;
    setUsbReveal(false);
    const t = setTimeout(() => setUsbReveal(true), 350);
    return () => clearTimeout(t);
  }, [usbOpen]);

  useEffect(() => {
    if (!papersOpen) return;
    setPapersReveal(false);
    const t = setTimeout(() => setPapersReveal(true), 350);
    return () => clearTimeout(t);
  }, [papersOpen]);

  useEffect(() => {
    const a = audioRef.current;
    if (!a) return;
    a.volume = 0.3;
    if (autoAdvanceRef.current) {
      autoAdvanceRef.current = false;
      const playNow = () => { a.play().catch(() => {}); };
      if (a.readyState >= 2) playNow();
      else a.addEventListener("canplay", playNow, { once: true });
    }
    const onTime = () => setProgress(a.duration ? a.currentTime / a.duration : 0);
    const onPlay = () => setIsPlaying(true);
    const onPause = () => setIsPlaying(false);
    const onEnded = () => { autoAdvanceRef.current = true; goNext(); };
    a.addEventListener("timeupdate", onTime);
    a.addEventListener("play", onPlay);
    a.addEventListener("pause", onPause);
    a.addEventListener("ended", onEnded);
    return () => {
      a.removeEventListener("timeupdate", onTime);
      a.removeEventListener("play", onPlay);
      a.removeEventListener("pause", onPause);
      a.removeEventListener("ended", onEnded);
    };
  }, [trackIndex]);

  const togglePlay = () => {
    if (!currentTrack || !audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.currentTime = 0;
      audioRef.current.play();
    }
  };
  const goNext = () => {
    if (!PLAYLIST.length) return;
    setProgress(0);
    setTrackIndex((i) => (i + 1) % PLAYLIST.length);
  };
  const goPrev = () => {
    if (!PLAYLIST.length) return;
    setProgress(0);
    setTrackIndex((i) => (i - 1 + PLAYLIST.length) % PLAYLIST.length);
  };
  const seekTo = (e) => {
    const a = audioRef.current;
    if (!a || !a.duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    a.currentTime = ratio * a.duration;
    setProgress(ratio);
  };

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") {
        setWelcomeOpen(false);
        close();
        setCardOpen(false);
        setIdCardOpen(false);
        setPlayerOpen(false);
        setUsbOpen(false);
        setActiveVideo(null);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [close]);

  return (
    <div className="page-root">
      <div className="lang-switch" role="group" aria-label="Language / Idioma">
        <button
          type="button"
          className={lang === "en" ? "active" : ""}
          onClick={() => setLang("en")}
        >
          EN
        </button>
        <button
          type="button"
          className={lang === "es" ? "active" : ""}
          onClick={() => setLang("es")}
        >
          ES
        </button>
      </div>
      <style>{`
        @import url(\'https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&family=Inter:wght@400;500;600&family=Caveat:wght@500;600&family=Permanent+Marker&display=swap\');

        html, body {
          margin: 0;
          padding: 0;
        }

        .page-root {
          --bg-top: #000000;
          --bg-bottom: #000000;
          --paper: #f6f3ec;
          --ink: #1c1a18;
          --accent: #7a1631;
          --accent-soft: #c98a9a;
          --metal-dark: #4a4844;

          position: relative;
          width: 100%;
          min-height: 100vh;
          background-color: #b1b2ad;
          font-family: \'Inter\', sans-serif;
          overflow-x: hidden;
        }

        .hero {
          position: relative;
          box-sizing: border-box;
          height: 100vh;
          height: 100svh;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: flex-end;
          padding: 20px 16px 20px;
          overflow: hidden;
        }

        .board-wrap {
          position: relative;
          z-index: 0;
          width: min(860px, 94vw, calc((100svh - 44px) / 1.6221));
          aspect-ratio: 631 / 1024;
          opacity: 0;
          transform: translateY(24px) scale(0.98);
          transition: opacity 0.9s ease, transform 0.9s cubic-bezier(.2,.8,.2,1);
        }
        .board-wrap.loaded {
          opacity: 1;
          transform: translateY(0) scale(1);
        }

        .desk-backdrop {
          position: absolute;
          z-index: -1;
          left: calc(-492 / 631 * 100%);
          top: calc(-98 / 1024 * 100%);
          width: calc(1654 / 631 * 100%);
          height: calc(1262 / 1024 * 100%);
          background-repeat: no-repeat;
          background-size: 100% 100%;
          pointer-events: none;
          mask-image: linear-gradient(to right,
            rgba(0,0,0,0) 0%, rgba(0,0,0,0.3) 6%, rgba(0,0,0,0.7) 12%, rgba(0,0,0,1) 20%,
            rgba(0,0,0,1) 80%, rgba(0,0,0,0.7) 88%, rgba(0,0,0,0.3) 94%, rgba(0,0,0,0) 100%);
          -webkit-mask-image: linear-gradient(to right,
            rgba(0,0,0,0) 0%, rgba(0,0,0,0.3) 6%, rgba(0,0,0,0.7) 12%, rgba(0,0,0,1) 20%,
            rgba(0,0,0,1) 80%, rgba(0,0,0,0.7) 88%, rgba(0,0,0,0.3) 94%, rgba(0,0,0,0) 100%);
        }

        .hotspot {
          position: absolute;
          border: none;
          background: rgba(255,255,255,0);
          border-radius: 10px;
          cursor: pointer;
          transition: background 0.25s ease, box-shadow 0.25s ease;
        }
        .hotspot:hover, .hotspot:focus-visible {
          background: rgba(255,255,255,0.12);
          box-shadow: 0 0 0 2px rgba(255,255,255,0.55), inset 0 0 0 1px rgba(255,255,255,0.3);
          outline: none;
        }
        .hotspot.pinged {
          animation: ping 0.4s ease;
        }
        @keyframes ping {
          0% { transform: scale(1); }
          50% { transform: scale(1.05); background: rgba(255,255,255,0.25); }
          100% { transform: scale(1); }
        }

        /* approximate regions on the 744x1206 reference photo, in % */
        .hotspot.memo      { left: 19%;   top: 13%;   width: 22.5%; height: 15.5%; }

        .overlay {
          position: fixed;
          inset: 0;
          background: rgba(20,18,16,0.55);
          backdrop-filter: blur(3px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 50;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
        }
        .overlay.open { opacity: 1; pointer-events: auto; }

        .panel {
          position: relative;
          background-color: var(--paper);
          background-image: none;
          background-size: cover;
          background-position: center;
          background-repeat: no-repeat;
          color: var(--ink);
          border-radius: 14px;
          box-shadow: 0 40px 80px -20px rgba(0,0,0,0.5);
          padding: 40px 36px;
          width: min(460px, 92vw);
          transform: scale(0.9) translateY(12px);
          transition: transform 0.4s cubic-bezier(.2,.8,.2,1);
        }
        .overlay.open .panel { transform: scale(1) translateY(0); }

        .panel-close {
          position: absolute;
          top: 14px;
          right: 14px;
          width: 28px;
          height: 28px;
          border-radius: 50%;
          border: 1px solid rgba(0,0,0,0.15);
          background: transparent;
          font-family: \'Space Mono\', monospace;
          font-size: 14px;
          color: var(--ink);
          cursor: pointer;
        }
        .panel-close:hover { background: rgba(0,0,0,0.06); }

        .panel-eyebrow {
          font-family: \'Space Mono\', monospace;
          font-size: 10px;
          letter-spacing: 0.15em;
          text-transform: uppercase;
          color: var(--accent);
          margin-bottom: 14px;
        }

        .bio-name {
          font-family: \'Inter\', sans-serif;
          font-weight: 600;
          font-size: 20px;
          margin-bottom: 10px;
        }
        .bio-hand {
          font-family: \'Caveat\', cursive;
          font-size: 26px;
          line-height: 1.35;
          color: #2b2620;
        }

        .contact-form {
          display: flex;
          flex-direction: column;
        }
        .contact-form-title, .contact-form-sent .contact-form-title {
          font-family: \'Space Mono\', monospace;
          font-weight: 700;
          font-size: 22px;
          letter-spacing: 0.02em;
          text-transform: uppercase;
          line-height: 1.3;
          color: #161310;
          margin-bottom: 10px;
        }
        .contact-form-subtitle {
          font-family: \'Space Mono\', monospace;
          font-weight: 400;
          font-size: 13px;
          line-height: 1.5;
          color: #161310;
          margin: 0 0 20px;
        }
        .contact-form-label {
          font-family: \'Space Mono\', monospace;
          font-weight: 700;
          font-size: 11px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: #161310;
          margin: 12px 0 4px;
        }
        .contact-form-input {
          font-family: \'Space Mono\', monospace;
          font-weight: 400;
          font-size: 14px;
          color: #161310;
          background: rgba(255,255,255,0.6);
          border: 1.5px solid rgba(0,0,0,0.25);
          border-radius: 4px;
          padding: 8px 11px;
          outline: none;
          transition: border-color 0.2s ease, box-shadow 0.2s ease;
        }
        .contact-form-input::placeholder {
          font-family: \'Space Mono\', monospace;
          font-weight: 400;
          color: rgba(22,19,16,0.45);
        }
        .contact-form-input:focus {
          border-color: #161310;
          box-shadow: 0 0 0 3px rgba(22,19,16,0.1);
        }
        .contact-form-textarea {
          resize: vertical;
          font-family: \'Space Mono\', monospace;
        }
        .contact-form-submit {
          margin-top: 20px;
          align-self: flex-start;
          font-family: \'Space Mono\', monospace;
          font-weight: 700;
          font-size: 13px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: var(--paper);
          background: #161310;
          border: none;
          border-radius: 999px;
          padding: 10px 28px;
          cursor: pointer;
          transition: transform 0.2s ease, background 0.2s ease;
        }
        .contact-form-error { margin: 8px 0 0; font-size: 10px; line-height: 1.5; color: #8a2b2b; }
        .contact-form-error a { color: inherit; text-decoration: underline; }
        .contact-form-submit:disabled { opacity: 0.6; cursor: default; }
        .contact-form-submit:hover {
          transform: scale(1.04);
          background: #000;
        }
        .contact-form-sent {
          padding: 8px 0 4px;
        }

        .tools-list {
          list-style: none;
          padding: 0;
          margin: 0;
          font-family: \'Space Mono\', monospace;
          font-size: 13px;
        }
        .tools-list li {
          padding: 8px 0;
          border-bottom: 1px dashed rgba(0,0,0,0.15);
          display: flex;
          align-items: center;
          gap: 8px;
        }
        .tools-list li::before {
          content: \'—\';
          color: var(--accent);
        }

        .contact-row {
          display: flex;
          flex-direction: column;
          gap: 12px;
          font-family: \'Inter\', sans-serif;
          font-size: 14px;
        }
        .contact-row a {
          color: var(--ink);
          text-decoration: none;
          border-bottom: 1px solid var(--accent);
          width: fit-content;
        }

        /* ---------- real business card prop on the board ---------- */
        .prop {
          position: absolute;
          cursor: pointer;
          border: none;
          padding: 0;
          background: none;
          background-color: transparent;
          transition: transform 0.35s cubic-bezier(.2,.8,.2,1), filter 0.35s ease, background-color 0.25s ease, box-shadow 0.25s ease;
          filter: drop-shadow(0 10px 16px rgba(0,0,0,0.22));
          border-radius: 6px;
        }
        .prop:hover, .prop:focus-visible {
          filter:
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6))
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6));
          outline: none;
        }

        /* Vibración sutil tipo notificación, para que se note que los
           elementos del escritorio se pueden clickear. Se detiene al pasar
           el cursor, para no interferir con el hover/tooltip. */
        .buzzable {
          animation: deskBuzz 2.5s ease-in-out infinite;
        }
        .buzzable:hover, .buzzable:focus-visible {
          animation-play-state: paused;
        }
        @keyframes deskBuzz {
          0% { transform: translate(0, 0) rotate(0deg); }
          3.5% { transform: translate(-0.92px, 0.4px) rotate(-0.63deg); }
          7% { transform: translate(0.92px, -0.4px) rotate(0.63deg); }
          10.5% { transform: translate(-0.92px, 0.4px) rotate(-0.63deg); }
          14% { transform: translate(0.69px, -0.29px) rotate(0.46deg); }
          17.5% { transform: translate(-0.69px, 0.29px) rotate(-0.46deg); }
          21%, 100% { transform: translate(0, 0) rotate(0deg); }
        }
        @media (prefers-reduced-motion: reduce) {
          .buzzable { animation: none; }
        }

        /* Tooltip que aparece al pasar el cursor por encima de un elemento
           clickeable del escritorio: un punto que aparece primero, una
           línea que se va dibujando hacia afuera y el texto (transparente,
           sin fondo, con un filo negro casi imperceptible) al final. */
        .prop-tooltip {
          position: absolute;
          width: 0;
          height: 0;
          pointer-events: none;
          z-index: 30;
        }
        .pt-dot {
          position: absolute;
          top: -3px;
          left: -3px;
          width: 6px;
          height: 6px;
          border-radius: 50%;
          background: #fff;
          box-shadow: 0 0 0 1px rgba(0,0,0,0.45);
          transform: scale(0);
          transition: transform 0.2s ease;
        }
        .pt-line {
          position: absolute;
          top: -0.5px;
          left: 0;
          width: 40px;
          height: 1px;
          background: #fff;
          box-shadow: 0 0 1px rgba(0,0,0,0.5);
          transform-origin: left center;
          transform: scaleX(0);
          transition: transform 0.3s ease 0.1s;
        }
        .pt-text {
          position: absolute;
          white-space: nowrap;
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: #fff;
          text-shadow: 0 0 2px rgba(0,0,0,0.65), 0 0 6px rgba(0,0,0,0.3);
          opacity: 0;
          transition: opacity 0.25s ease 0.38s;
        }
        .proptip:hover .pt-dot, .proptip:focus-visible .pt-dot { transform: scale(1); }
        .proptip:hover .pt-text, .proptip:focus-visible .pt-text { opacity: 1; }

        .dir-r { top: 50%; left: 100%; }
        .dir-r .pt-line { transform: rotate(0deg) scaleX(0); }
        .proptip:hover .dir-r .pt-line, .proptip:focus-visible .dir-r .pt-line { transform: rotate(0deg) scaleX(1); }
        .dir-r .pt-text { left: 50px; top: -7px; text-align: left; }

        .dir-dr { top: 100%; left: 100%; }
        .dir-dr .pt-line { transform: rotate(45deg) scaleX(0); }
        .proptip:hover .dir-dr .pt-line, .proptip:focus-visible .dir-dr .pt-line { transform: rotate(45deg) scaleX(1); }
        .dir-dr .pt-text { left: 35px; top: 32px; text-align: left; }

        .dir-d { top: 100%; left: 50%; }
        .dir-d .pt-line { transform: rotate(90deg) scaleX(0); }
        .proptip:hover .dir-d .pt-line, .proptip:focus-visible .dir-d .pt-line { transform: rotate(90deg) scaleX(1); }
        .dir-d .pt-text { left: 0; top: 48px; transform: translateX(-50%); text-align: center; }

        .dir-dl { top: 100%; left: 0; }
        .dir-dl .pt-line { transform: rotate(135deg) scaleX(0); }
        .proptip:hover .dir-dl .pt-line, .proptip:focus-visible .dir-dl .pt-line { transform: rotate(135deg) scaleX(1); }
        .dir-dl .pt-text { left: -35px; top: 32px; transform: translateX(-100%); text-align: right; }

        .dir-l { top: 50%; left: 0; }
        .dir-l .pt-line { transform: rotate(180deg) scaleX(0); }
        .proptip:hover .dir-l .pt-line, .proptip:focus-visible .dir-l .pt-line { transform: rotate(180deg) scaleX(1); }
        .dir-l .pt-text { left: -50px; top: -7px; transform: translateX(-100%); text-align: right; }

        .dir-ul { top: 0; left: 0; }
        .dir-ul .pt-line { transform: rotate(-135deg) scaleX(0); }
        .proptip:hover .dir-ul .pt-line, .proptip:focus-visible .dir-ul .pt-line { transform: rotate(-135deg) scaleX(1); }
        .dir-ul .pt-text { left: -35px; top: -32px; transform: translate(-100%,-100%); text-align: right; }
        .prop-label {
          position: absolute;
          bottom: -18px;
          left: 0;
          right: 0;
          font-family: 'Space Mono', monospace;
          font-size: 9px;
          letter-spacing: 0.1em;
          color: var(--metal-dark);
          text-transform: uppercase;
          text-align: center;
          opacity: 0;
          transition: opacity 0.25s ease;
        }
        .prop:hover .prop-label { opacity: 0.85; }

        .prop.realcard {
          top: 33%;
          left: 55%;
          width: 32%;
          aspect-ratio: 3702 / 2360;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          transform: rotate(-3deg);
          --hover-transform: rotate(-3deg);
          filter: drop-shadow(3px 4px 1px rgba(20,18,15,0.38));
        }
        .prop.realcard:hover {
          filter:
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6))
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6));
        }

        .prop.idcardprop {
          top: 77.5%;
          left: 15%;
          width: 32%;
          aspect-ratio: 1600 / 1021;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          transform: rotate(-5deg);
          --hover-transform: rotate(-5deg) scale(1.05);
          z-index: 3;
          filter: drop-shadow(3px 4px 1px rgba(20,18,15,0.38));
        }
        .prop.idcardprop:hover {
          filter:
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6))
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6));
        }

        /* ---------- identity card enlarge modal ---------- */
        .idcard-overlay {
          position: fixed;
          inset: 0;
          background: rgba(20,18,16,0.92);
          backdrop-filter: blur(18px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 60;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
        }
        .idcard-overlay.open { opacity: 1; pointer-events: auto; }

        .idcard-stage {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          transform: scale(0.85);
          transition: transform 0.45s cubic-bezier(.2,.8,.2,1);
          perspective: 900px;
        }
        .idcard-overlay.open .idcard-stage { transform: scale(1); }

        .idcard-close {
          position: absolute;
          top: -44px;
          right: 0;
          width: 32px;
          height: 32px;
          border-radius: 50%;
          border: 1px solid rgba(255,255,255,0.4);
          background: rgba(0,0,0,0.2);
          color: var(--paper);
          font-family: 'Space Mono', monospace;
          font-size: 16px;
          cursor: pointer;
        }
        .idcard-close:hover { background: rgba(0,0,0,0.4); }

        .idcard-frame {
          position: relative;
          width: min(80vw, 520px);
          aspect-ratio: 1600 / 1021;
        }
        .idcard-tilt {
          position: absolute;
          inset: 0;
          filter: drop-shadow(0 30px 50px rgba(0,0,0,0.55));
          transition: transform 0.12s ease-out;
          will-change: transform;
        }
        .idcard-face {
          position: absolute;
          inset: 0;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          border-radius: 4.5%;
          overflow: hidden;
        }
        .idcard-shine {
          position: absolute;
          inset: 0;
          pointer-events: none;
          mix-blend-mode: overlay;
          opacity: 0;
          transition: opacity 0.3s ease, background-position 0.08s linear;
          background-image: linear-gradient(
            115deg,
            rgba(255,255,255,0) 35%,
            rgba(255,255,255,0.44) 46%,
            rgba(255,255,255,0.72) 50%,
            rgba(255,255,255,0.44) 54%,
            rgba(255,255,255,0) 65%
          );
          background-size: 220% 220%;
        }

        .idcard-annot {
          position: absolute;
          inset: 0;
          pointer-events: none;
        }
        .idcard-annot-svg {
          position: absolute;
          inset: 0;
          width: 100%;
          height: 100%;
          overflow: visible;
        }
        .idcard-annot-line {
          stroke: #fff;
          stroke-width: 2px;
          vector-effect: non-scaling-stroke;
        }
        .idcard-annot-dot {
          fill: #fff;
        }
        .idcard-annot-label {
          position: absolute;
          transform: translate(-50%, -50%);
          border: 1px solid #fff;
          padding: 3px 7px;
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.05em;
          color: #fff;
          white-space: nowrap;
          background: rgba(20,18,16,0.35);
        }
        .idcard-annot-bio {
          position: absolute;
          transform: translateY(-100%);
          width: 150px;
          margin: 0;
          font-family: 'Space Mono', monospace;
          font-size: 9.5px;
          line-height: 1.45;
          letter-spacing: 0.01em;
          color: #fff;
        }
        .idcard-annot-blankbox {
          position: absolute;
          border: 1.5px solid #fff;
          background: rgba(20,18,16,0.55);
          overflow: hidden;
        }
        .idcard-annot-stampimg {
          position: absolute;
          inset: 0;
          background-repeat: no-repeat;
          filter: grayscale(1) invert(1) contrast(1.35);
          mix-blend-mode: screen;
          opacity: 0.92;
        }
        .idcard-annot-vert {
          position: absolute;
          right: -3px;
          top: 50%;
          transform: translate(100%, -50%) rotate(90deg);
          transform-origin: left center;
          font-family: 'Space Mono', monospace;
          font-size: 9px;
          letter-spacing: 0.08em;
          color: #fff;
          white-space: nowrap;
          background: rgba(20,18,16,0.55);
          padding: 0 2px;
        }
        .idcard-annot-logo {
          position: absolute;
          width: 63px;
          height: 63px;
          border-radius: 50%;
          border: 1.5px solid #fff;
          transform: translate(-50%, -50%);
          overflow: hidden;
          background-repeat: no-repeat;
          filter: drop-shadow(0 3px 6px rgba(0,0,0,0.7));
        }

        /* ---------- flip card modal ---------- */
        .card-overlay {
          position: fixed;
          inset: 0;
          background: rgba(20,18,16,0.92);
          backdrop-filter: blur(18px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 60;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
        }
        .card-overlay.open { opacity: 1; pointer-events: auto; }

        .card-stage {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          transform: scale(0.85);
          transition: transform 0.45s cubic-bezier(.2,.8,.2,1);
          perspective: 900px;
        }
        .card-overlay.open .card-stage { transform: scale(1); }

        .card-close {
          position: absolute;
          top: -44px;
          right: 0;
          width: 32px;
          height: 32px;
          border-radius: 50%;
          border: 1px solid rgba(255,255,255,0.4);
          background: rgba(0,0,0,0.2);
          color: var(--paper);
          font-family: 'Space Mono', monospace;
          font-size: 16px;
          cursor: pointer;
        }
        .card-close:hover { background: rgba(0,0,0,0.4); }

        .card-clip {
          position: relative;
          width: min(68vw, 360px);
          aspect-ratio: 3702 / 2360;
          filter: drop-shadow(0 30px 50px rgba(0,0,0,0.55));
          border-radius: 5%;
          overflow: hidden;
          transition: transform 0.12s ease-out;
          will-change: transform;
        }
        .card-flip {
          position: relative;
          width: 100%;
          height: 100%;
          cursor: pointer;
          perspective: 1600px;
        }
        .card-flip-inner {
          position: relative;
          width: 100%;
          height: 100%;
          transform-style: preserve-3d;
          -webkit-transform-style: preserve-3d;
          transition: transform 0.6s cubic-bezier(.4,.2,.2,1);
          transform: rotateY(0deg);
        }
        .card-flip.flipped .card-flip-inner {
          transform: rotateY(180deg);
        }
        .card-face {
          position: absolute;
          inset: 0;
          border-radius: 5%;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          backface-visibility: hidden;
          -webkit-backface-visibility: hidden;
          transition: background-position 0.08s linear;
        }
        .card-face-back {
          transform: rotateY(180deg);
        }

        /* ---------- ipod + headphones music player ---------- */
        .prop.ipodprop {
          top: 44.51%;
          left: 59%;
          width: 28.63%;
          aspect-ratio: 420 / 650;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          transform: rotate(3deg);
          --hover-transform: rotate(3deg) scale(1.04);
          filter: drop-shadow(6px 8px 1px rgba(20,18,15,0.4));
        }
        .prop.ipodprop:hover {
          filter:
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6))
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6));
        }

        .player-overlay {
          position: fixed;
          inset: 0;
          background: rgba(20,18,16,0.6);
          backdrop-filter: blur(4px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 60;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
        }
        .player-overlay.open { opacity: 1; pointer-events: auto; }

        .player-stage {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          transform: scale(0.85);
          transition: transform 0.45s cubic-bezier(.2,.8,.2,1);
          width: min(82vw, 340px);
        }
        .player-overlay.open .player-stage { transform: scale(1); }

        .player-close {
          position: absolute;
          top: -44px;
          right: 0;
          width: 32px;
          height: 32px;
          border-radius: 50%;
          border: 1px solid rgba(255,255,255,0.4);
          background: rgba(0,0,0,0.2);
          color: var(--paper);
          font-family: 'Space Mono', monospace;
          font-size: 16px;
          cursor: pointer;
        }
        .player-close:hover { background: rgba(0,0,0,0.4); }

        .player-scene {
          position: relative;
          width: 100%;
          height: 300px;
        }

        .player-photo {
          position: absolute;
          left: 50%;
          top: 0;
          width: 220px;
          transform-origin: top center;
          transform: translateX(-50%) scale(0.5);
          opacity: 0;
          filter: drop-shadow(0 14px 26px rgba(0,0,0,0.4));
          transition: opacity 0.5s ease, transform 0.6s cubic-bezier(.3,1,.4,1);
        }
        .player-scene.unwound .player-photo {
          opacity: 1;
          transform: translateX(-50%) scale(1);
        }
        .player-photo img { display: block; width: 100%; }

        .player-screen-glow {
          position: absolute;
          left: 47%;
          top: 35%;
          width: 21%;
          height: 12%;
          background: radial-gradient(ellipse, rgba(255,255,255,0.95), rgba(255,255,255,0) 70%);
          opacity: 0;
          border-radius: 6%;
          pointer-events: none;
        }
        .player-scene.unwound .player-screen-glow {
          animation: screenOn 0.9s ease 0.35s;
        }
        @keyframes screenOn {
          0%   { opacity: 0; }
          25%  { opacity: 0.95; }
          55%  { opacity: 0.15; }
          100% { opacity: 0; }
        }

        /* ---------- one big, forgiving, fully invisible click zone over the click-wheel ---------- */
        .player-hotspot {
          position: absolute;
          left: 58%;
          top: 56%;
          width: 30%;
          height: 13%;
          transform: translate(-50%, -50%);
          z-index: 3;
          border: none;
          background: transparent;
          padding: 0;
          cursor: pointer;
        }

        /* ---------- transparent arrow + instructions (no box, white text) ---------- */
        .player-hint {
          margin-top: 12px;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 4px;
        }
        .player-hint-line {
          width: 1px;
          height: 13px;
          background: rgba(255,255,255,0.55);
        }
        .player-hint-label {
          font-family: 'Space Mono', monospace;
          font-size: 10.5px;
          letter-spacing: 0.12em;
          text-transform: uppercase;
          color: #fff;
          text-shadow: 0 1px 4px rgba(0,0,0,0.6);
          text-align: center;
          cursor: pointer;
          background: none;
          border: none;
          padding: 0;
        }
        .player-hint-track {
          font-family: 'Space Mono', monospace;
          font-size: 9px;
          letter-spacing: 0.05em;
          color: rgba(255,255,255,0.72);
          text-align: center;
          max-width: 230px;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }

        .card-hint {
          margin-top: 18px;
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.12em;
          text-transform: uppercase;
          color: rgba(255,255,255,0.7);
        }

        /* ---------- USB drive prop ---------- */
        .prop.usbprop {
          top: 36%;
          left: 28%;
          width: 20.8%;
          aspect-ratio: 700 / 333;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          transform: rotate(-6deg);
          --hover-transform: rotate(-6deg) scale(1.06);
          z-index: 3;
          filter: drop-shadow(4px 5px 1px rgba(20,18,15,0.38));
        }
        .prop.usbprop:hover {
          filter:
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6))
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6));
        }

        /* ---------- Pen (decorative, left edge of the clipboard) ---------- */
        .pen-prop {
          position: absolute;
          top: 10%;
          left: 4%;
          width: 2.4%;
          aspect-ratio: 59 / 1150;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          transform: rotate(-4deg);
          transform-origin: center;
          z-index: 3;
          pointer-events: none;
          filter: drop-shadow(3px 4px 2px rgba(20,18,15,0.3));
        }

        /* ---------- Papeles prop (ficha de proyectos, sobre el bloc con clip) ---------- */
        .prop.papersprop {
          top: 43.9%;
          left: 20.9%;
          width: 32.9%;
          aspect-ratio: 659 / 784;
          background-size: contain;
          background-repeat: no-repeat;
          background-position: center;
          border-radius: 2px;
          filter: drop-shadow(3px 4px 1px rgba(20,18,15,0.35));
          transform: rotate(-2deg);
          --hover-transform: rotate(-2deg) scale(1.06);
          z-index: 3;
        }
        .prop.papersprop:hover {
          filter:
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6))
            drop-shadow(0 0 1.5px rgba(255,255,255,0.6));
        }

        /* ---------- USB video-portfolio gallery ---------- */
        .usb-overlay {
          position: fixed;
          inset: 0;
          background: rgba(142,140,133,0.38);
          backdrop-filter: blur(5px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 60;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
        }
        .usb-overlay.open { opacity: 1; pointer-events: auto; }

        .usb-stage {
          position: relative;
          width: min(94vw, 780px);
          height: min(86vh, 600px);
          background: rgba(237,235,229,0.88);
          backdrop-filter: blur(26px) saturate(1.15);
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 30px 70px rgba(35,33,30,0.35), inset 0 0 0 1px rgba(255,255,255,0.6);
          transform: scale(0.9);
          transition: transform 0.45s cubic-bezier(.2,.8,.2,1);
          display: flex;
        }
        .usb-overlay.open .usb-stage { transform: scale(1); }

        /* ventana estilo Finder: barra lateral con "semáforo" genérico
           (los tres puntos son una convención de UI común, no un logo) */
        .usb-sidebar {
          width: 148px;
          flex-shrink: 0;
          background: rgba(255,255,255,0.3);
          border-right: 1px solid rgba(40,38,34,0.08);
          padding: 16px 0 16px 18px;
          box-sizing: border-box;
          display: flex;
          flex-direction: column;
          gap: 24px;
        }
        .usb-traffic { display: flex; gap: 8px; align-items: center; }
        .usb-dot {
          width: 12px;
          height: 12px;
          border-radius: 50%;
          border: none;
          padding: 0;
          box-shadow: inset 0 0 0 0.5px rgba(0,0,0,0.15);
        }
        .usb-dot-red { background: #ff5f57; cursor: pointer; }
        .usb-dot-yellow { background: #febc2e; cursor: default; }
        .usb-dot-green { background: #28c840; cursor: default; }
        .usb-nav {
          display: flex;
          flex-direction: column;
          gap: 14px;
        }
        .usb-nav-item {
          font-family: 'Space Mono', monospace;
          font-size: 10.5px;
          letter-spacing: 0.02em;
          color: rgba(50,48,44,0.6);
          background: none;
          border: none;
          padding: 3px 0;
          margin: 0;
          text-align: left;
          cursor: pointer;
          border-radius: 4px;
          transition: color 0.15s ease;
        }
        .usb-nav-item:hover { color: rgba(40,38,34,0.85); }
        .usb-nav-item.active { color: #3b7dd8; font-weight: 700; }
        .usb-nav-item.active:hover { color: #3b7dd8; }

        .usb-content {
          flex: 1;
          min-width: 0;
          display: flex;
          flex-direction: column;
        }
        .usb-content-header {
          flex-shrink: 0;
          padding: 20px 22px 8px;
          font-family: 'Space Mono', monospace;
          font-size: 15px;
          font-weight: 700;
          letter-spacing: 0.01em;
          color: #2a2925;
        }
        .usb-content-body {
          position: relative;
          flex: 1;
          overflow: hidden;
        }

        .ig-grid {
          position: relative;
          height: 100%;
          overflow-y: auto;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 22px;
          padding: 20px 20px 48px;
          box-sizing: border-box;
        }
        .ig-card {
          width: 100%;
          max-width: 300px;
          flex: none;
          background: #ffffff;
          border-radius: 12px;
          overflow: hidden;
          box-shadow: 0 10px 24px rgba(0,0,0,0.35);
          opacity: 0;
          transform: translateY(14px);
          transition: opacity 0.4s ease, transform 0.4s cubic-bezier(.2,.8,.2,1);
        }
        .usb-stage.revealed .ig-card { opacity: 1; transform: translateY(0); }
        .ig-card-header {
          display: flex;
          align-items: center;
          gap: 9px;
          padding: 10px 12px;
        }
        .ig-avatar {
          width: 30px;
          height: 30px;
          border-radius: 50%;
          flex: none;
          display: flex;
          align-items: center;
          justify-content: center;
          font-family: 'Inter', sans-serif;
          font-size: 12px;
          font-weight: 700;
          color: rgba(30,28,24,0.55);
        }
        .ig-handle-col { flex: 1; min-width: 0; }
        .ig-handle {
          font-family: 'Inter', sans-serif;
          font-size: 13px;
          font-weight: 600;
          color: #1c1a18;
        }
        .ig-dots {
          font-family: 'Inter', sans-serif;
          font-size: 13px;
          letter-spacing: 1px;
          color: rgba(28,26,24,0.45);
        }
        .ig-image {
          width: 100%;
          aspect-ratio: 1 / 1;
          background: #eee;
        }
        .ig-image img { width: 100%; height: 100%; object-fit: cover; object-position: top center; display: block; }
        button.ig-image.ig-image-clickable {
          border: none;
          padding: 0;
          margin: 0;
          display: block;
          cursor: pointer;
          font: inherit;
        }
        button.ig-image.ig-image-clickable:hover img { filter: brightness(1.04); }
        .ig-actions {
          display: flex;
          align-items: center;
          gap: 13px;
          padding: 10px 12px 4px;
        }
        .ig-icon { width: 21px; height: 21px; color: #1c1a18; flex: none; }
        .ig-icon-bookmark { margin-left: auto; }
        .ig-likes {
          font-family: 'Inter', sans-serif;
          font-size: 12.5px;
          font-weight: 700;
          color: #1c1a18;
          padding: 2px 12px 0;
        }
        .ig-caption {
          font-family: 'Inter', sans-serif;
          font-size: 12.5px;
          line-height: 1.45;
          color: #1c1a18;
          padding: 4px 12px 0;
        }
        .ig-caption .ig-handle { font-size: 12.5px; margin-right: 4px; }
        .ig-date {
          font-family: 'Inter', sans-serif;
          font-size: 10.5px;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          color: rgba(28,26,24,0.4);
          padding: 6px 12px 12px;
        }

        .board-card {
          width: 100%;
          max-width: 300px;
          flex: none;
          background: transparent;
          border-radius: 0;
          overflow: visible;
          box-shadow: none;
          opacity: 0;
          transform: translateY(14px);
          transition: opacity 0.4s ease, transform 0.4s cubic-bezier(.2,.8,.2,1);
        }
        .usb-stage.revealed .board-card { opacity: 1; transform: translateY(0); }
        .board-card-image {
          width: 100%;
          background: transparent;
        }
        .board-card-image img { width: 100%; height: auto; display: block; }
        .board-card-label {
          font-family: 'Space Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.03em;
          text-transform: uppercase;
          color: rgba(28,26,24,0.55);
          text-align: center;
          padding: 10px 12px 12px;
        }

        .atm-card {
          width: 100%;
          max-width: 300px;
          flex: none;
          background: transparent;
          border-radius: 10px;
          overflow: hidden;
          box-shadow: 0 10px 24px rgba(0,0,0,0.35);
          opacity: 0;
          transform: translateY(14px);
          transition: opacity 0.4s ease, transform 0.4s cubic-bezier(.2,.8,.2,1);
        }
        .usb-stage.revealed .atm-card { opacity: 1; transform: translateY(0); }
        .atm-card img { width: 100%; height: auto; display: block; }
        .atm-card-label {
          font-family: 'Space Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.03em;
          text-transform: uppercase;
          color: rgba(28,26,24,0.55);
          text-align: center;
          padding: 10px 12px 12px;
          background: transparent;
        }

        .menu-tile-card {
          width: 100%;
          max-width: 300px;
          flex: none;
          position: relative;
          aspect-ratio: 4 / 3;
          border: none;
          padding: 0;
          cursor: pointer;
          border-radius: 12px;
          overflow: hidden;
          background: #1c1b18;
          box-shadow: 0 10px 24px rgba(0,0,0,0.35);
          opacity: 0;
          transform: translateY(14px);
          transition: opacity 0.4s ease, transform 0.4s cubic-bezier(.2,.8,.2,1);
        }
        .usb-stage.revealed .menu-tile-card { opacity: 1; transform: translateY(0); }
        .menu-tile-bg {
          position: absolute;
          inset: 0;
          background-size: cover;
          background-position: center;
          transition: transform 0.5s ease;
        }
        .menu-tile-card:hover .menu-tile-bg { transform: scale(1.06); }
        .menu-tile-scrim {
          position: absolute;
          inset: 0;
          background: linear-gradient(to top, rgba(10,9,8,0.85) 0%, rgba(10,9,8,0.08) 58%, rgba(10,9,8,0.22) 100%);
        }
        .menu-tile-text {
          position: absolute;
          left: 14px;
          right: 14px;
          bottom: 12px;
          text-align: left;
        }
        .menu-tile-title {
          font-family: 'Space Mono', monospace;
          font-size: 13px;
          letter-spacing: 0.04em;
          text-transform: uppercase;
          color: #f6f3ec;
        }
        .menu-tile-sub {
          font-family: 'Space Mono', monospace;
          font-size: 9.5px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: rgba(246,243,236,0.65);
          margin-top: 5px;
          display: flex;
          align-items: center;
          gap: 6px;
        }

        .menu-book-stage.open { opacity: 1; pointer-events: auto; }
        .menu-book-inner {
          position: absolute;
          inset: 0;
          background-size: cover;
          background-position: center;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
        }
        .menu-book-scrim { position: absolute; inset: 0; background: rgba(8,7,6,0.5); }
        .menu-book-topbar {
          position: absolute;
          top: 14px;
          left: 14px;
          right: 14px;
          display: flex;
          align-items: center;
          justify-content: space-between;
          z-index: 3;
        }
        .menu-book-round-btn {
          width: 32px;
          height: 32px;
          border-radius: 50%;
          background: rgba(10,9,8,0.55);
          border: 1px solid rgba(255,255,255,0.3);
          color: #f6f3ec;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          flex: none;
        }
        .menu-book-round-btn:hover { background: rgba(10,9,8,0.8); }
        .menu-book-heading {
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          color: #f6f3ec;
          background: rgba(10,9,8,0.45);
          padding: 6px 12px;
          border-radius: 20px;
          text-align: center;
        }
        .menu-book-spread {
          position: relative;
          z-index: 2;
          display: flex;
          align-items: stretch;
          justify-content: center;
          gap: 2px;
          width: 88%;
          max-width: 560px;
          transition: max-width 0.35s ease;
        }
        .menu-book-spread.flippable { cursor: ew-resize; }
        .menu-book-spread.zoomed { max-width: 820px; width: 94%; }
        .menu-book-spread.one-page { max-width: 320px; }
        .menu-book-spread.one-page.zoomed { max-width: 460px; }
        .menu-book-page {
          flex: 1;
          min-width: 0;
          background: #faf6ee;
          box-shadow: 0 20px 60px rgba(0,0,0,0.55);
          border-radius: 3px;
          overflow: hidden;
          max-height: 70vh;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .menu-book-spread.two-page .menu-book-page:first-child {
          border-radius: 3px 0 0 3px;
          box-shadow: -10px 20px 40px rgba(0,0,0,0.45), inset -6px 0 10px -8px rgba(0,0,0,0.35);
        }
        .menu-book-spread.two-page .menu-book-page:last-child {
          border-radius: 0 3px 3px 0;
          box-shadow: 10px 20px 40px rgba(0,0,0,0.45), inset 6px 0 10px -8px rgba(0,0,0,0.35);
        }
        .menu-book-page img {
          width: 100%;
          height: 100%;
          object-fit: contain;
          display: block;
          max-height: 70vh;
        }
        .menu-book-dots {
          position: absolute;
          bottom: 42px;
          display: flex;
          gap: 6px;
          z-index: 3;
        }
        .menu-book-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(246,243,236,0.35); }
        .menu-book-dot.active { background: #f6f3ec; }
        .menu-book-hint {
          position: absolute;
          bottom: 18px;
          font-family: 'Space Mono', monospace;
          font-size: 9px;
          letter-spacing: 0.05em;
          text-transform: uppercase;
          color: rgba(246,243,236,0.5);
          z-index: 3;
          text-align: center;
          padding: 0 20px;
        }

        .usb-empty-category {
          position: absolute;
          inset: 0;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          gap: 14px;
          text-align: center;
          padding: 0 30px;
        }
        .usb-empty-icon {
          width: 56px;
          height: 56px;
          border-radius: 14px;
          background: linear-gradient(160deg, rgba(50,48,44,0.12), rgba(50,48,44,0.05));
          border: 1.5px dashed rgba(50,48,44,0.25);
        }
        .usb-empty-text {
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: rgba(50,48,44,0.45);
          max-width: 220px;
        }

        .usb-bg-placeholder {
          position: absolute;
          left: 50%;
          top: 2%;
          width: 56%;
          max-width: 320px;
          transform: translateX(-50%);
          filter: blur(11px);
          opacity: 0.65;
          pointer-events: none;
        }
        .usb-bg-head {
          width: 60%;
          margin: 0 auto;
          aspect-ratio: 1 / 1;
          border-radius: 50%;
          background: linear-gradient(160deg, #9a978f, #55534e);
        }
        .usb-bg-shoulders {
          width: 100%;
          height: 42%;
          margin-top: -8%;
          border-radius: 50% 50% 0 0 / 60% 60% 0 0;
          background: linear-gradient(160deg, #86837b, #46443f);
        }
        .usb-bg-note {
          position: absolute;
          left: 50%;
          top: 7%;
          transform: translateX(-50%);
          font-family: 'Space Mono', monospace;
          font-size: 9px;
          letter-spacing: 0.12em;
          text-transform: uppercase;
          color: rgba(60,58,52,0.45);
          text-align: center;
          width: 100%;
          pointer-events: none;
        }
        .usb-photo {
          position: absolute;
          left: 50%;
          top: 0;
          width: 50%;
          max-width: 280px;
          transform: translateX(-50%);
          display: block;
          pointer-events: none;
        }

        .usb-folders {
          position: relative;
          height: 100%;
          display: flex;
          flex-wrap: wrap;
          align-content: center;
          justify-content: center;
          gap: 34px 40px;
          padding: 24px;
          box-sizing: border-box;
        }
        .usb-folder {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 8px;
          width: 110px;
          border: none;
          background: none;
          padding: 0;
          cursor: pointer;
        }
        .usb-folder-icon {
          width: 76px;
          height: 64px;
          filter: drop-shadow(0 6px 10px rgba(28,26,24,0.22));
          transition: transform 0.2s ease;
        }
        .usb-folder:hover .usb-folder-icon,
        .usb-folder:focus-visible .usb-folder-icon {
          transform: scale(1.06) translateY(-2px);
        }
        .usb-folder-label {
          font-family: 'Inter', sans-serif;
          font-weight: 600;
          font-size: 12px;
          color: #2a2925;
          text-align: center;
          line-height: 1.3;
        }
        .usb-folder-count {
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          color: rgba(42,41,37,0.55);
        }
        .usb-folder-view {
          position: relative;
          height: 100%;
          display: flex;
          flex-direction: column;
          min-height: 0;
        }
        .usb-folder-back {
          position: relative;
          z-index: 2;
          flex: none;
          align-self: flex-start;
          margin: 14px 0 0 18px;
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.06em;
          text-transform: uppercase;
          color: #f4f6f8;
          background: rgba(0,0,0,0.35);
          border: 1px solid rgba(255,255,255,0.25);
          border-radius: 999px;
          padding: 6px 12px;
          cursor: pointer;
        }
        .usb-folder-back:hover { background: rgba(0,0,0,0.5); }
        .usb-thumb-fallback {
          width: 100%;
          aspect-ratio: 9 / 16;
          border-radius: 22%;
          background: linear-gradient(145deg, #3a3a3a, #1c1c1c);
          box-shadow: 0 10px 20px rgba(0,0,0,0.4);
        }

        .usb-gallery {
          position: relative;
          flex: 1;
          min-height: 0;
          overflow-y: auto;
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(84px, 1fr));
          gap: 40px 16px;
          align-content: start;
          padding: 22px 24px 56px;
          box-sizing: border-box;
        }

        .usb-thumb {
          position: relative;
          width: 100%;
          max-width: 110px;
          transform: scale(0.85);
          opacity: 0;
          border: none;
          background: none;
          padding: 0;
          cursor: pointer;
          transition: opacity 0.4s ease, transform 0.4s cubic-bezier(.2,.8,.2,1);
        }
        .usb-stage.revealed .usb-thumb {
          opacity: 1;
          transform: scale(1);
        }
        .usb-thumb img {
          display: block;
          width: 100%;
          border-radius: 22%;
          box-shadow: 0 10px 20px rgba(0,0,0,0.4);
          transition: transform 0.25s ease;
        }
        .usb-thumb:hover img, .usb-thumb:focus-visible img { transform: scale(1.08); }
        .usb-thumb-label {
          position: absolute;
          left: 0;
          right: 0;
          top: calc(100% + 6px);
          width: 100%;
          white-space: normal;
          overflow-wrap: break-word;
          line-height: 1.35;
          text-align: center;
          font-family: 'Space Mono', monospace;
          font-size: 8px;
          letter-spacing: 0.06em;
          text-transform: uppercase;
          color: rgba(38,36,32,0.85);
          text-shadow: 0 1px 2px rgba(255,255,255,0.65);
        }

        .usb-gallery-hint {
          position: absolute;
          left: 50%;
          bottom: 18px;
          transform: translateX(-50%);
          font-family: 'Space Mono', monospace;
          font-size: 9px;
          letter-spacing: 0.12em;
          text-transform: uppercase;
          color: rgba(60,58,52,0.5);
          text-align: center;
        }

        /* Mazo de tarjetas apiladas (folders de video y de menú). */
        .card-stack-wrap {
          flex: 1;
          min-height: 0;
          display: flex;
          align-items: flex-start;
          justify-content: center;
          overflow: auto;
          padding: 26px 40px 90px 20px;
          box-sizing: border-box;
        }
        .card-stack {
          position: relative;
          width: min(230px, 56vw);
          height: 340px;
          margin: 0 auto;
          cursor: ew-resize;
        }
        .card-stack-item {
          position: absolute;
          top: 0;
          left: 0;
          width: 200px;
          max-width: 100%;
          height: 260px;
          border: none;
          border-radius: 14px;
          overflow: hidden;
          padding: 0;
          cursor: pointer;
          background: #1c1b18;
          box-shadow: 0 16px 34px rgba(0,0,0,0.45);
          transition: transform 0.4s cubic-bezier(.2,.8,.2,1);
          transform-origin: top left;
        }
        .card-stack-item img {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: cover;
        }
        .card-stack-fallback {
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          background: linear-gradient(145deg, #3a3a3a, #1c1c1c);
          color: rgba(246,243,236,0.6);
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          text-transform: uppercase;
          letter-spacing: 0.08em;
        }
        .card-stack-label-row {
          position: absolute;
          left: 0;
          right: 0;
          bottom: 0;
          display: flex;
          align-items: center;
          justify-content: flex-start;
          gap: 8px;
          padding: 10px 12px;
          background: linear-gradient(to top, rgba(0,0,0,0.82), rgba(0,0,0,0));
        }
        .card-stack-label {
          font-family: 'Space Mono', monospace;
          font-size: 9.5px;
          line-height: 1.3;
          letter-spacing: 0.03em;
          text-transform: uppercase;
          color: #f6f3ec;
          text-align: left;
        }
        .usb-image-frame {
          aspect-ratio: auto;
          max-height: 80vh;
          background: #f6f3ec;
        }
        .usb-image-frame img {
          width: 100%;
          height: 100%;
          max-height: 80vh;
          object-fit: contain;
        }

        .usb-video-stage {
          position: absolute;
          inset: 0;
          background: rgba(10,9,8,0.94);
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          gap: 14px;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.3s ease;
          z-index: 50;
        }
        .usb-video-stage.open { opacity: 1; pointer-events: auto; }
        .usb-video-frame {
          width: 88%;
          max-width: 620px;
          aspect-ratio: 16 / 9;
          background: #000;
          border-radius: 8px;
          overflow: hidden;
          display: flex;
          align-items: center;
          justify-content: center;
          box-shadow: 0 20px 50px rgba(0,0,0,0.6);
        }
        .usb-video-frame video { width: 100%; height: 100%; object-fit: contain; }
        .usb-video-iframe { width: 100%; height: 100%; border: 0; }
        .usb-video-placeholder {
          color: rgba(246,243,236,0.55);
          font-family: 'Space Mono', monospace;
          font-size: 10.5px;
          letter-spacing: 0.06em;
          text-transform: uppercase;
          text-align: center;
          padding: 0 24px;
          line-height: 1.6;
        }
        .usb-video-title {
          font-family: 'Space Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          color: var(--paper);
        }
        .usb-video-back {
          font-family: 'Space Mono', monospace;
          font-size: 9.5px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          color: rgba(246,243,236,0.65);
          background: none;
          border: 1px solid rgba(255,255,255,0.3);
          border-radius: 20px;
          padding: 6px 16px;
          cursor: pointer;
        }
        .usb-video-back:hover { background: rgba(255,255,255,0.08); color: #fff; }

        /* ---------- Papeles — galería de proyectos ---------- */
        .papers-overlay {
          position: fixed;
          inset: 0;
          background: rgba(142,140,133,0.38);
          backdrop-filter: blur(5px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 60;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
        }
        .papers-overlay.open { opacity: 1; pointer-events: auto; }

        .papers-stage {
          position: relative;
          width: min(96vw, 644px);
          height: min(94vh, 1008px);
          overflow: visible;
          transform: scale(0.9);
          transition: transform 0.45s cubic-bezier(.2,.8,.2,1);
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .papers-overlay.open .papers-stage { transform: scale(1); }

        .papers-close {
          position: absolute;
          top: -14px;
          right: -14px;
          width: 34px;
          height: 34px;
          border-radius: 50%;
          border: none;
          background: rgba(30,28,25,0.85);
          color: #f5f2ea;
          font-size: 20px;
          line-height: 1;
          font-family: 'Space Mono', monospace;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 80;
          box-shadow: 0 6px 14px rgba(0,0,0,0.3);
          transition: transform 0.15s ease, background 0.15s ease;
        }
        .papers-close:hover { background: #000; transform: scale(1.08); }

        .papers-deck {
          position: relative;
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
        }
        .papers-deck-hint {
          position: absolute;
          left: 0;
          right: 0;
          bottom: -30px;
          text-align: center;
          font-family: 'Space Mono', monospace;
          font-size: 10px;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          color: rgba(255,253,248,0.75);
          pointer-events: none;
        }

        .paper-card-deck-tag {
          position: absolute;
          top: 14px;
          right: 16px;
          font-family: 'Space Mono', monospace;
          font-size: 8.5px;
          letter-spacing: 0.06em;
          text-transform: uppercase;
          color: rgba(50,48,44,0.55);
          background: rgba(50,48,44,0.08);
          padding: 4px 8px;
          border-radius: 20px;
        }

        .paper-card {
          position: absolute;
          background: #f5f2ea;
          border-radius: 4px;
          box-shadow: 0 18px 34px rgba(20,18,15,0.4), 0 4px 10px rgba(20,18,15,0.22);
          box-sizing: border-box;
          overflow: hidden;
          transition: transform 0.5s cubic-bezier(.22,.9,.3,1), opacity 0.5s ease;
        }
        .paper-card-deck {
          width: min(90vw, 532px);
          aspect-ratio: 659 / 784;
        }
        .paper-card-deck.is-front { cursor: pointer; }
        .paper-card-deck.has-page-image {
          background: transparent;
          box-shadow: none;
          overflow: visible;
        }

        .paper-card-deck-page-wrap {
          position: relative;
          width: 100%;
          height: 100%;
          container-type: inline-size;
        }
        .paper-card-deck-page-img {
          display: block;
          width: 100%;
          height: 100%;
          object-fit: contain;
          object-position: center;
          pointer-events: none;
        }
        .paper-overlay-caption {
          position: absolute;
          left: 31%;
          width: 39%;
          top: 43.3%;
          text-align: center;
          font-family: 'Space Mono', monospace;
          font-size: 2cqw;
          line-height: 1.3;
          color: #29231a;
          pointer-events: none;
        }
        .paper-overlay-body {
          position: absolute;
          left: 20.3%;
          width: 64.7%;
          top: 52.8%;
          bottom: 3.5%;
          font-family: 'Space Mono', monospace;
          color: #29231a;
          pointer-events: none;
          overflow: hidden;
        }
        .paper-overlay-row {
          margin: 0 0 1.6cqw;
          font-size: 2.25cqw;
          line-height: 1.4;
        }
        .paper-overlay-label {
          font-weight: 700;
        }
        .paper-overlay-date {
          font-style: italic;
        }
        .paper-overlay-desc {
          margin: 0 0 2.4cqw;
          font-size: 2.1cqw;
          line-height: 1.55;
        }
        .paper-overlay-more {
          margin: 0.4cqw 0 0;
          font-size: 1.85cqw;
          letter-spacing: 0.04em;
          text-transform: uppercase;
          text-decoration: underline;
          text-underline-offset: 2px;
          cursor: pointer;
          pointer-events: auto;
          display: inline-block;
        }
        .paper-overlay-more:hover { opacity: 0.6; }

        .morephotos-overlay {
          position: fixed;
          inset: 0;
          background: rgba(20,18,16,0.55);
          backdrop-filter: blur(6px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 85;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.35s ease;
          padding: 24px;
        }
        .morephotos-overlay.open { opacity: 1; pointer-events: auto; }
        .morephotos-stage {
          position: relative;
          width: min(92vw, 640px);
          max-height: 90vh;
          overflow-y: auto;
          transform: scale(0.92);
          transition: transform 0.45s cubic-bezier(.2,.8,.2,1);
          padding: 44px 20px 30px;
        }
        .morephotos-overlay.open .morephotos-stage { transform: scale(1); }
        .morephotos-close {
          position: absolute;
          top: 2px;
          right: 2px;
          width: 34px;
          height: 34px;
          border-radius: 50%;
          border: none;
          background: rgba(30,28,25,0.85);
          color: #f5f2ea;
          font-size: 20px;
          line-height: 1;
          font-family: 'Space Mono', monospace;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 10;
          box-shadow: 0 6px 14px rgba(0,0,0,0.3);
          transition: transform 0.15s ease, background 0.15s ease;
        }
        .morephotos-close:hover { background: #000; transform: scale(1.08); }
        .morephotos-title {
          font-family: 'Space Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          color: rgba(255,255,255,0.75);
          text-align: center;
          margin: 0 0 22px;
        }
        .morephotos-grid {
          display: flex;
          flex-wrap: wrap;
          justify-content: center;
          align-items: flex-start;
          gap: 26px 18px;
          padding: 10px 6px 20px;
        }
        .morephotos-item {
          width: 44%;
          min-width: 150px;
          max-width: 260px;
          background: #fff;
          padding: 6px;
          border-radius: 3px;
          box-shadow: 0 12px 26px rgba(0,0,0,0.35);
          transform: rotate(var(--rot, 0deg));
          transition: transform 0.2s ease;
        }
        .morephotos-item:hover { transform: rotate(0deg) scale(1.03); }
        .morephotos-item img {
          display: block;
          width: 100%;
          height: auto;
          border-radius: 1px;
        }
        .morephotos-item.single {
          width: 70%;
          max-width: 340px;
        }

        .paper-card-deck-wip {
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .paper-card-deck-wip-text {
          font-family: 'Space Mono', monospace;
          font-size: 11px;
          letter-spacing: 0.1em;
          text-transform: uppercase;
          color: rgba(60,58,52,0.4);
        }


        /* ================= Pulido tipo macOS ================= */
        * { -webkit-tap-highlight-color: transparent; }
        button { transition-property: transform, filter, background-color, opacity, box-shadow, color, border-color; }
        button:active:not(:disabled) { filter: brightness(0.92); }

        /* Ventanas: abrir con resorte suave, cerrar rápido y limpio */
        .card-overlay, .idcard-overlay, .player-overlay, .usb-overlay, .papers-overlay, .morephotos-overlay {
          backdrop-filter: blur(0px);
          -webkit-backdrop-filter: blur(0px);
          transition: opacity 0.26s cubic-bezier(.4,0,.6,1), backdrop-filter 0.4s ease, -webkit-backdrop-filter 0.4s ease;
        }
        .card-overlay.open, .idcard-overlay.open, .player-overlay.open, .usb-overlay.open, .papers-overlay.open, .morephotos-overlay.open {
          backdrop-filter: blur(9px) saturate(1.08);
          -webkit-backdrop-filter: blur(9px) saturate(1.08);
          transition: opacity 0.3s cubic-bezier(.2,.7,.2,1), backdrop-filter 0.45s ease, -webkit-backdrop-filter 0.45s ease;
        }
        .card-stage, .idcard-stage, .player-stage, .usb-stage, .papers-stage, .morephotos-stage {
          transform: scale(0.92) translateY(14px);
          opacity: 0;
          transform-origin: 50% 60%;
          transition: transform 0.26s cubic-bezier(.4,0,1,1), opacity 0.2s ease-in, width 0.5s cubic-bezier(.3,.8,.2,1), height 0.5s cubic-bezier(.3,.8,.2,1);
          will-change: transform, opacity;
        }
        .card-overlay.open .card-stage,
        .idcard-overlay.open .idcard-stage,
        .player-overlay.open .player-stage,
        .usb-overlay.open .usb-stage,
        .papers-overlay.open .papers-stage,
        .morephotos-overlay.open .morephotos-stage {
          transform: scale(1) translateY(0);
          opacity: 1;
          transition: transform 0.6s cubic-bezier(.18,1.12,.3,1), opacity 0.32s ease-out, width 0.5s cubic-bezier(.3,.8,.2,1), height 0.5s cubic-bezier(.3,.8,.2,1);
        }

        /* Semáforo: minimizar (efecto "genie") y maximizar */
        .usb-overlay.open .usb-stage.minimizing {
          transform: translateY(62vh) scale(0.12);
          transform-origin: 50% 100%;
          opacity: 0;
          transition: transform 0.42s cubic-bezier(.55,0,.8,.3), opacity 0.34s ease-in 0.06s;
        }
        .usb-stage.maximized { width: min(98vw, 1200px); height: min(95vh, 860px); }
        .usb-traffic { gap: 8px; }
        .usb-dot { position: relative; cursor: pointer; transition: transform 0.12s ease, filter 0.12s ease; }
        .usb-dot:active { transform: scale(0.84); filter: brightness(0.85); }
        .usb-dot::after {
          position: absolute; inset: 0;
          display: flex; align-items: center; justify-content: center;
          font: 700 9px/12px 'Space Mono', monospace;
          color: rgba(60,20,10,0.68);
          opacity: 0;
          transition: opacity 0.12s ease;
        }
        .usb-traffic:hover .usb-dot::after { opacity: 1; }
        .usb-dot-red::after { content: "×"; font-size: 12px; }
        .usb-dot-yellow::after { content: "−"; }
        .usb-dot-green::after { content: "+"; }

        /* Cambio de categoría: fundido con ligero deslizamiento */
        .usb-content-body { animation: usbCatIn 0.42s cubic-bezier(.2,.8,.2,1) both; }
        @keyframes usbCatIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

        /* Video: carga con velo y aparición suave */
        .usb-video-stage { transform: scale(1.04); transition: opacity 0.3s ease, transform 0.45s cubic-bezier(.2,.8,.2,1); }
        .usb-video-stage.open { transform: scale(1); }
        .usb-video-loading {
          width: 100%; height: 100%; background-size: cover; background-position: center; background-color: #000;
          position: relative; border-radius: inherit; overflow: hidden;
        }
        .usb-video-loading-veil {
          position: absolute; inset: 0; background: rgba(8,7,6,0.55);
          display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px;
          backdrop-filter: blur(3px);
        }
        .usb-video-spinner {
          width: 26px; height: 26px; border-radius: 50%;
          border: 2px solid rgba(255,255,255,0.25); border-top-color: #fff;
          animation: usbSpin 0.8s linear infinite;
        }
        @keyframes usbSpin { to { transform: rotate(360deg); } }
        .usb-video-loading-pct { font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 0.08em; color: rgba(255,255,255,0.8); min-height: 12px; }
        .usb-video-ready { animation: usbVidIn 0.5s ease both; }
        @keyframes usbVidIn { from { opacity: 0; } to { opacity: 1; } }


        /* El botón de cerrar vibra un poco, unos segundos después de abrir un
           elemento, para insinuar que ya terminaste con él y sigue el siguiente. */
        .card-overlay.open .card-close,
        .idcard-overlay.open .idcard-close,
        .player-overlay.open .player-close,
        .papers-overlay.open .papers-close,
        .usb-overlay.open .usb-dot-red {
          animation: closeBuzz 2.5s ease-in-out 3.5s infinite;
        }
        .card-overlay.open .card-close:hover,
        .idcard-overlay.open .idcard-close:hover,
        .player-overlay.open .player-close:hover,
        .papers-overlay.open .papers-close:hover,
        .usb-overlay.open .usb-dot-red:hover { animation: none; }
        @keyframes closeBuzz {
          0% { transform: translate(0, 0) rotate(0deg) scale(1); }
          4% { transform: translate(-1.6px, 0.6px) rotate(-9deg) scale(1.12); }
          8% { transform: translate(1.6px, -0.6px) rotate(9deg) scale(1.12); }
          12% { transform: translate(-1.4px, 0.5px) rotate(-7deg) scale(1.1); }
          16% { transform: translate(1.2px, -0.4px) rotate(6deg) scale(1.06); }
          20%, 100% { transform: translate(0, 0) rotate(0deg) scale(1); }
        }
        @media (prefers-reduced-motion: reduce) {
          .card-overlay.open .card-close, .idcard-overlay.open .idcard-close, .player-overlay.open .player-close,
          .papers-overlay.open .papers-close, .usb-overlay.open .usb-dot-red { animation: none; }
        }

        /* ===== Pantalla de entrada ===== */
        .enter-gate {
          position: fixed; inset: 0; z-index: 90;
          display: flex; align-items: center; justify-content: center;
          background: rgba(40,38,34,0.18);
          backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px);
          cursor: pointer;
          transition: opacity 0.4s ease, backdrop-filter 0.5s ease, -webkit-backdrop-filter 0.5s ease;
        }
        .enter-gate.gone { opacity: 0; pointer-events: none; backdrop-filter: blur(0px); -webkit-backdrop-filter: blur(0px); }
        .enter-pill {
          display: inline-flex; align-items: center; gap: 10px;
          font-family: 'Space Mono', monospace; font-size: 13px; letter-spacing: 0.04em;
          color: #2b2a27; background: rgba(246,244,239,0.92);
          padding: 12px 20px; border-radius: 999px;
          box-shadow: 0 10px 30px rgba(35,33,30,0.25), inset 0 0 0 1px rgba(255,255,255,0.7);
          animation: enterPulse 2.2s ease-in-out infinite;
        }
        .enter-dot { width: 8px; height: 8px; border-radius: 50%; background: #ff5f57; }
        @keyframes enterPulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.05); } }

        /* ===== Ventana de bienvenida ===== */
        .welcome-overlay {
          position: fixed; inset: 0; z-index: 70;
          display: flex; align-items: center; justify-content: center;
          background: rgba(40,38,34,0.28);
          opacity: 0; pointer-events: none;
          backdrop-filter: blur(0px); -webkit-backdrop-filter: blur(0px);
          transition: opacity 0.26s cubic-bezier(.4,0,.6,1), backdrop-filter 0.4s ease, -webkit-backdrop-filter 0.4s ease;
        }
        .welcome-overlay.open {
          opacity: 1; pointer-events: auto;
          backdrop-filter: blur(6px) saturate(1.05); -webkit-backdrop-filter: blur(6px) saturate(1.05);
          transition: opacity 0.3s cubic-bezier(.2,.7,.2,1), backdrop-filter 0.45s ease, -webkit-backdrop-filter 0.45s ease;
        }
        .welcome-window {
          width: min(94vw, 760px);
          background: #f6f4ef;
          border-radius: 13px;
          overflow: hidden;
          box-shadow: 0 30px 70px rgba(35,33,30,0.38), inset 0 0 0 1px rgba(255,255,255,0.7);
          transform: scale(0.92) translateY(14px); opacity: 0;
          transition: transform 0.26s cubic-bezier(.4,0,1,1), opacity 0.2s ease-in;
        }
        .welcome-overlay.open .welcome-window {
          transform: scale(1) translateY(0); opacity: 1;
          transition: transform 0.6s cubic-bezier(.18,1.12,.3,1), opacity 0.32s ease-out;
        }
        .welcome-bar {
          display: flex; align-items: center; gap: 10px;
          background: #e6e4df; padding: 11px 14px;
        }
        .welcome-nav {
          width: 22px; height: 22px; border-radius: 50%; background: #f8f7f4; color: #77746d;
          display: flex; align-items: center; justify-content: center; flex: none;
        }
        .welcome-address {
          flex: 1; min-width: 0; height: 22px; border-radius: 999px; background: #f8f7f4;
          display: flex; align-items: center; justify-content: space-between; gap: 8px;
          padding: 0 10px 0 12px; color: #77746d;
          font-family: 'Space Mono', monospace; font-size: 10px; letter-spacing: 0.02em;
        }
        .welcome-address span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .welcome-dots { display: flex; flex-direction: column; gap: 2.5px; padding: 0 3px; flex: none; }
        .welcome-dots i { width: 3px; height: 3px; border-radius: 50%; background: #aaa7a0; display: block; }
        .welcome-body { padding: 26px 30px 26px; font-family: 'Space Mono', monospace; color: #2a2925; }
        .welcome-title { font-size: 19px; font-weight: 700; letter-spacing: 0.01em; min-height: 28px; margin-bottom: 14px; white-space: pre-wrap; }
        .welcome-cols { display: flex; gap: 26px; align-items: center; }
        .welcome-main { flex: 1; min-width: 0; }
        .welcome-blocks { display: flex; flex-direction: column; gap: 11px; }
        .welcome-block { font-size: 12px; line-height: 1.65; opacity: 0; transform: translateY(5px); transition: opacity 0.3s ease, transform 0.4s cubic-bezier(.2,.8,.2,1); white-space: pre-wrap; }
        .welcome-block.on { opacity: 1; transform: none; }
        .welcome-block.lead { font-size: 14px; font-weight: 700; letter-spacing: 0.01em; margin-top: 2px; }
        .welcome-block.item { display: flex; gap: 10px; align-items: baseline; padding-left: 2px; }
        .welcome-block.item .welcome-block-text { flex: 1; min-width: 0; }
        .welcome-tag {
          flex: none; min-width: 66px; text-align: center; font-size: 9.5px; letter-spacing: 0.1em; font-weight: 700;
          background: #2a2925; color: #f6f4ef; padding: 2px 8px; border-radius: 999px;
        }
        .welcome-doll {
          flex: none; height: min(380px, 56vh); width: auto; align-self: center;
          filter: drop-shadow(0 10px 12px rgba(35,33,30,0.22));
          opacity: 0; transform: translateY(14px) scale(0.94);
          user-select: none; -webkit-user-drag: none;
        }
        .welcome-overlay.open .welcome-doll { animation: welcomeDollPop 0.8s 0.55s cubic-bezier(.2,1.25,.3,1) both, welcomeDollBob 4.2s 1.5s ease-in-out infinite; }
        @keyframes welcomeDollPop { from { opacity: 0; transform: translateY(18px) scale(0.92); } to { opacity: 1; transform: none; } }
        @keyframes welcomeDollBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
        .welcome-scr { opacity: 0.55; }
        .welcome-ok {
          margin-top: 18px; font-family: 'Space Mono', monospace; font-size: 10.5px; letter-spacing: 0.08em; text-transform: uppercase;
          background: #2a2925; color: #f6f4ef; border: none; border-radius: 999px; padding: 9px 18px; cursor: pointer;
          opacity: 0; transform: translateY(6px); pointer-events: none;
          transition: opacity 0.4s ease, transform 0.4s cubic-bezier(.2,.8,.2,1), background 0.2s ease;
        }
        .welcome-ok.show { opacity: 1; transform: none; pointer-events: auto; }
        .welcome-ok:hover { background: #46443f; }
        .welcome-ok:active { transform: scale(0.96); }
        @media (max-width: 560px) {
          .welcome-body { padding: 18px 18px 18px; }
          .welcome-cols { gap: 12px; align-items: flex-end; }
          .welcome-block { font-size: 11px; }
          .welcome-doll { height: 190px; }
          .welcome-tag { min-width: 54px; font-size: 8.5px; }
        }
        /* Menús: escenas con scroll vertical */
        .menu-scenes {
          position: absolute; inset: 0;
          overflow-y: auto; overflow-x: hidden;
          scroll-snap-type: y mandatory;
          scroll-behavior: smooth;
          overscroll-behavior: contain;
        }
        .menu-scenes::-webkit-scrollbar { width: 0; }
        .menu-scene {
          position: relative;
          width: 100%; height: 100%; min-height: 100%;
          scroll-snap-align: start; scroll-snap-stop: always;
          background-size: cover; background-position: center;
          display: flex; flex-direction: column; align-items: center; justify-content: center;
          overflow: hidden;
        }
        .menu-book-spacer { width: 32px; height: 32px; flex: none; }
        .menu-book-spread.flippable { cursor: pointer; }
        .menu-book-spread { transition: max-width 0.5s cubic-bezier(.2,.8,.2,1), transform 0.2s ease; outline: none; }
        .menu-book-spread.flippable:active { transform: scale(0.992); }
        .menu-book-page { animation: menuPageIn 0.55s cubic-bezier(.2,.8,.2,1) both; transform-origin: left center; }
        .menu-book-spread.two-page .menu-book-page:first-child { transform-origin: right center; }
        @keyframes menuPageIn {
          from { opacity: 0; transform: perspective(900px) rotateY(-16deg) translateX(14px) scale(0.985); }
          to { opacity: 1; transform: none; }
        }
        .menu-book-dot { transition: background 0.25s ease, transform 0.25s ease; }
        .menu-book-dot.active { transform: scale(1.3); }
        .menu-book-hint {
          font-size: 10px; letter-spacing: 0.06em; color: rgba(246,243,236,0.92);
          background: rgba(10,9,8,0.5); padding: 6px 14px; border-radius: 20px; bottom: 14px;
          animation: menuHintPulse 2.4s ease-in-out infinite;
        }
        @keyframes menuHintPulse { 0%,100% { opacity: 0.65; } 50% { opacity: 1; } }
        .menu-book-dots { bottom: 52px; }
        .menu-scroll-cue {
          position: absolute; right: 16px; bottom: 14px; z-index: 3;
          width: 30px; height: 30px; border-radius: 50%;
          background: rgba(10,9,8,0.55); border: 1px solid rgba(255,255,255,0.3); color: #f6f3ec;
          display: flex; align-items: center; justify-content: center;
          animation: menuCueBounce 1.6s ease-in-out infinite;
          pointer-events: none;
        }
        @keyframes menuCueBounce { 0%,100% { transform: translateY(0); } 50% { transform: translateY(5px); } }
        .menu-book-round-btn { transition: background 0.2s ease, transform 0.15s ease; }
        .menu-book-round-btn:active { transform: scale(0.88); }

        /* Menús: sin foto de fondo, mismo gris de la ventana */
        .menu-scene { background: transparent; border-bottom: 1px solid rgba(40,38,34,0.07); }
        .menu-book-scrim { display: none; }
        .menu-book-heading { background: rgba(255,255,255,0.55); color: #2a2925; box-shadow: inset 0 0 0 1px rgba(40,38,34,0.08); }
        .menu-book-round-btn { background: rgba(255,255,255,0.6); border: 1px solid rgba(40,38,34,0.14); color: #2a2925; }
        .menu-book-round-btn:hover { background: rgba(255,255,255,0.9); }
        .menu-book-page { box-shadow: 0 14px 38px rgba(35,33,30,0.26); }
        .menu-book-spread.two-page .menu-book-page:first-child { box-shadow: -8px 14px 32px rgba(35,33,30,0.22), inset -6px 0 10px -8px rgba(0,0,0,0.3); }
        .menu-book-spread.two-page .menu-book-page:last-child { box-shadow: 8px 14px 32px rgba(35,33,30,0.22), inset 6px 0 10px -8px rgba(0,0,0,0.3); }

        /* Páginas del menú: sin marco blanco, la imagen manda */
        .menu-scene { --bh: min(calc(min(86vh, 600px) - 172px), calc((min(94vw, 780px) - 196px) / 1.45 - 56px)); }
        .usb-stage.maximized .menu-scene { --bh: min(calc(min(95vh, 860px) - 172px), calc((min(98vw, 1200px) - 196px) / 1.45 - 56px)); }
        .menu-scene .menu-book-spread { width: auto; max-width: 94%; gap: 0; }
        .menu-scene .menu-book-spread.zoomed, .menu-scene .menu-book-spread.one-page, .menu-scene .menu-book-spread.one-page.zoomed { width: auto; max-width: 94%; }
        .menu-scene .menu-book-page { flex: 0 0 auto; background: transparent; max-height: none; line-height: 0; display: block; }
        .menu-scene .menu-book-page img { display: block; width: auto; height: var(--bh); max-height: none; max-width: none; object-fit: fill; transition: height 0.5s cubic-bezier(.2,.8,.2,1); }
        .menu-scene .menu-book-spread.zoomed .menu-book-page img { height: calc(var(--bh) + 56px); }
        .menu-book-dot { background: rgba(40,38,34,0.25); }
        .menu-book-dot.active { background: #2a2925; }
        .menu-book-hint { background: rgba(255,255,255,0.6); color: #2a2925; box-shadow: inset 0 0 0 1px rgba(40,38,34,0.08); }
        .menu-scroll-cue { background: rgba(255,255,255,0.6); border: 1px solid rgba(40,38,34,0.14); color: #2a2925; }

        @media (prefers-reduced-motion: reduce) {
          .board-wrap, .panel, .overlay { transition: opacity 0.2s ease !important; transform: none !important; }
          .card-flip-inner { transition: none !important; }
          .player-photo { transition: none !important; }
          .usb-thumb, .usb-stage, .usb-video-stage { transition: none !important; }
          .paper-card { transition: none !important; }
        }

        .lang-switch {
          position: fixed;
          top: 7px;
          left: 50%;
          transform: translateX(-50%);
          z-index: 9999;
          display: flex;
          background: rgba(28,26,24,0.9);
          border: 1px solid rgba(255,255,255,0.18);
          border-radius: 999px;
          padding: 2px;
          gap: 1px;
          backdrop-filter: blur(4px);
        }
        .lang-switch button {
          font-family: 'Space Mono', monospace;
          font-size: 8.5px;
          letter-spacing: 0.08em;
          font-weight: 700;
          border: none;
          background: transparent;
          color: rgba(255,255,255,0.55);
          padding: 3px 9px;
          border-radius: 999px;
          cursor: pointer;
          transition: background 0.2s ease, color 0.2s ease;
        }
        .lang-switch button:hover {
          color: rgba(255,255,255,0.85);
        }
        .lang-switch button.active {
          background: #f6f3ec;
          color: #1c1a18;
        }
        @media (max-width: 640px) {
          .lang-switch { top: 6px; }
          .lang-switch button { padding: 3px 8px; font-size: 8px; }
        }
        @media (max-aspect-ratio: 3/4) {
          .hero { justify-content: center; }
        }

        /* ===== Móvil (celular) ===== */
        @media (max-width: 640px) {
          /* Ventana del USB: a casi toda la pantalla, categorías en una franja arriba */
          .usb-stage, .usb-stage.maximized {
            width: calc(100vw - 12px);
            height: calc(100vh - 76px);
            height: calc(100dvh - 76px);
            flex-direction: column;
          }
          .usb-sidebar {
            width: 100%; flex-shrink: 0; flex-direction: column; gap: 10px;
            padding: 12px 14px 10px; border-right: none;
            border-bottom: 1px solid rgba(40,38,34,0.08);
          }
          .usb-traffic { gap: 10px; }
          .usb-dot { width: 15px; height: 15px; }
          .usb-nav { flex-direction: row; gap: 8px; justify-content: space-between; overflow-x: auto; scrollbar-width: none; }
          .usb-nav::-webkit-scrollbar { display: none; }
          .usb-nav-item { font-size: clamp(8.5px, 2.5vw, 10.5px); letter-spacing: 0; padding: 4px 0; white-space: nowrap; flex: none; }
          .usb-content { min-height: 0; }
          .usb-content-header { padding: 14px 16px 6px; font-size: 14px; }
          .ig-card { max-width: 350px; }
          .ig-grid { padding: 14px 12px 48px; }

          /* Mazo de videos más grande */
          .card-stack-wrap { padding: 16px 12px 90px; justify-content: center; }
          .card-stack { width: min(66vw, 290px); height: calc(min(66vw, 290px) * 1.3 + 70px); touch-action: pan-y; }
          .card-stack-item { width: min(66vw, 290px); height: calc(min(66vw, 290px) * 1.3); }
          .card-stack-label { font-size: 11px; }

          /* Tarjeta ID: cabe completa con sus etiquetas */
          .idcard-frame { width: calc((100vw - 28px) / 1.5); }
          .idcard-overlay .idcard-stage, .idcard-overlay.open .idcard-stage { transform: none; perspective: none; will-change: auto; }
          .idcard-close {
            position: fixed; top: 56px; right: 14px; width: 46px; height: 46px;
            font-size: 24px; background: rgba(0,0,0,0.5);
          }
          .idcard-annot-bio { width: 128px; }
          .card-clip { width: min(86vw, 360px); }

          /* Botón de cerrar grande y fijo arriba a la derecha en las demás ventanas */
          .card-overlay .card-stage, .card-overlay.open .card-stage,
          .player-overlay .player-stage, .player-overlay.open .player-stage,
          .papers-overlay .papers-stage, .papers-overlay.open .papers-stage { transform: none; perspective: none; will-change: auto; }
          .card-close, .player-close, .papers-close {
            position: fixed; top: 56px; right: 14px; left: auto; width: 46px; height: 46px;
            font-size: 24px; background: rgba(20,18,16,0.7); border: 1px solid rgba(255,255,255,0.4); z-index: 90;
          }

          /* "Más fotos": una columna grande y botón de cerrar fijo y grande */
          .morephotos-overlay { padding: 0; align-items: stretch; justify-content: stretch; }
          .morephotos-overlay .morephotos-stage, .morephotos-overlay.open .morephotos-stage {
            width: 100%; height: 100%; max-height: none; box-sizing: border-box;
            padding: 64px 12px 40px; transform: none; will-change: auto;
          }
          .morephotos-close {
            position: sticky; top: 8px; right: auto; margin: -52px 0 6px auto;
            width: 46px; height: 46px; font-size: 26px;
          }
          .morephotos-grid { gap: 30px 0; padding: 6px 0 24px; }
          .morephotos-item { width: 88%; max-width: 360px; min-width: 0; }
          .morephotos-item.single { width: 92%; max-width: 380px; }

          /* Menús: una página a la vez, a todo lo ancho */
          .menu-book-spacer, .menu-book-round-btn { display: none; }
          .menu-book-topbar { justify-content: center; }
          .menu-scene .menu-book-spread, .menu-scene .menu-book-spread.zoomed,
          .menu-scene .menu-book-spread.one-page, .menu-scene .menu-book-spread.one-page.zoomed { width: auto; max-width: 96%; }
          .menu-scene .menu-book-page img, .menu-scene .menu-book-spread.zoomed .menu-book-page img {
            width: auto; height: auto; max-width: calc(100vw - 44px);
            max-height: calc(100vh - 330px); max-height: calc(100dvh - 330px);
            object-fit: contain;
          }
        }
      `}</style>

      <section className="hero">
        <div className={`board-wrap ${loaded ? "loaded" : ""}`}>
          <div className="desk-backdrop" style={{ backgroundImage: `url(${DESK_FULL_IMG})` }} />
          <div className="pen-prop" style={{ backgroundImage: `url(${PEN_PROP_IMG})` }} aria-hidden="true" />
          <button
            className="hotspot memo proptip"
            onClick={() => setActive("bio")}
            aria-label={t('viewBio')}
          >
            <span className="prop-tooltip dir-ul">
              <span className="pt-dot" />
              <span className="pt-line" />
              <span className="pt-text">{t('tooltipContact')}</span>
            </span>
          </button>
          <button
            className={`prop papersprop proptip ${nextBuzzStep === 4 && !welcomeOpen ? "buzzable" : ""}`}
            onClick={() => { markBuzzVisited(4); setPapersOpen(true); setPapersReveal(false); setDeckOrder(ALL_PROJECTS.map((_, i) => i)); }}
            aria-label={t('viewProjectGallery')}
            style={{ backgroundImage: `url(${PAPERS_PROP_IMG_DESK})` }}
          >
            <span className="prop-tooltip dir-dl">
              <span className="pt-dot" />
              <span className="pt-line" />
              <span className="pt-text">{t('tooltipPortfolio')}</span>
            </span>
          </button>
          <button
            className={`prop realcard proptip ${nextBuzzStep === 5 && !welcomeOpen ? "buzzable" : ""}`}
            onClick={() => { markBuzzVisited(5); setCardOpen(true); setCardFlipped(false); }}
            aria-label={t('viewContactCard')}
            style={{ backgroundImage: `url(${CARD_FRONT_IMG})` }}
          >
            <span className="prop-tooltip dir-r">
              <span className="pt-dot" />
              <span className="pt-line" />
              <span className="pt-text">{t('tooltipBusinessCard')}</span>
            </span>
          </button>
          <button
            className={`prop idcardprop proptip ${nextBuzzStep === 2 && !welcomeOpen ? "buzzable" : ""}`}
            onClick={() => { markBuzzVisited(2); setIdCardOpen(true); }}
            aria-label={t('viewPresentationCard')}
            style={{ backgroundImage: `url(${IDCARD_PROP_IMG})` }}
          >
            <span className="prop-tooltip dir-d">
              <span className="pt-dot" />
              <span className="pt-line" />
              <span className="pt-text">{t('tooltipPresentationCard')}</span>
            </span>
          </button>
          <button
            className={`prop ipodprop proptip ${nextBuzzStep === 1 && !welcomeOpen ? "buzzable" : ""}`}
            onClick={() => { markBuzzVisited(1); setPlayerOpen(true); setPlayerReveal(false); }}
            aria-label={t('listenPlaylist')}
            style={{ backgroundImage: `url(${WRAPPED_IPOD_IMG})` }}
          >
            <span className="prop-tooltip dir-dr">
              <span className="pt-dot" />
              <span className="pt-line" />
              <span className="pt-text">{t('tooltipMusic')}</span>
            </span>
          </button>
          <button
            className={`prop usbprop proptip ${nextBuzzStep === 3 && !welcomeOpen ? "buzzable" : ""}`}
            onClick={() => { markBuzzVisited(3); setUsbOpen(true); setUsbReveal(false); setActiveVideo(null); setActiveFolder(null); setActiveMenuFolder(null); setUsbCategory("video"); }}
            aria-label={t('viewVideoPortfolio')}
            style={{ backgroundImage: `url(${USB_PROP_IMG})` }}
          >
            <span className="prop-tooltip dir-l">
              <span className="pt-dot" />
              <span className="pt-line" />
              <span className="pt-text">{t('tooltipMyWork')}</span>
            </span>
          </button>
        </div>

      </section>

      <div className={`overlay ${active ? "open" : ""}`} onClick={close}>
        <div className="panel" onClick={(e) => e.stopPropagation()} style={{ backgroundImage: `url(${POSTIT_NOTE_IMG})` }}>
          <button className="panel-close" onClick={close} aria-label={t('close')}>
            &times;
          </button>

          {active === "bio" && (
            <>
              <div className="panel-eyebrow">{t('bioEyebrow')}</div>
              {!contactSent ? (
                <form className="contact-form" onSubmit={handleContactSubmit}>
                  <div className="contact-form-title">
                    <ScrambleText key={`cftitle-${lang}-${active === "bio"}`} text={t('contactFormTitle')} play={active === "bio"} speed={22} />
                  </div>
                  <p className="contact-form-subtitle">{t('contactFormSubtitle')}</p>

                  <label className="contact-form-label" htmlFor="cf-name">{t('contactFormNameLabel')}</label>
                  <input
                    id="cf-name"
                    className="contact-form-input"
                    type="text"
                    required
                    placeholder={t('contactFormNamePlaceholder')}
                    value={contactForm.name}
                    onChange={(e) => setContactForm((f) => ({ ...f, name: e.target.value }))}
                  />

                  <label className="contact-form-label" htmlFor="cf-contact">{t('contactFormContactLabel')}</label>
                  <input
                    id="cf-contact"
                    className="contact-form-input"
                    type="text"
                    required
                    placeholder={t('contactFormContactPlaceholder')}
                    value={contactForm.contact}
                    onChange={(e) => setContactForm((f) => ({ ...f, contact: e.target.value }))}
                  />

                  <label className="contact-form-label" htmlFor="cf-message">{t('contactFormMessageLabel')}</label>
                  <textarea
                    id="cf-message"
                    className="contact-form-input contact-form-textarea"
                    rows={3}
                    placeholder={t('contactFormMessagePlaceholder')}
                    value={contactForm.message}
                    onChange={(e) => setContactForm((f) => ({ ...f, message: e.target.value }))}
                  />

                  <button type="submit" className="contact-form-submit" disabled={contactSending}>
                    {contactSending ? t('contactFormSending') : t('contactFormSubmit')}
                  </button>
                  {contactError && (
                    <p className="contact-form-error">
                      {t('contactFormError')}{" "}
                      <a href={`mailto:${CONTACT_EMAIL}`}>{CONTACT_EMAIL}</a>
                    </p>
                  )}
                </form>
              ) : (
                <div className="contact-form-sent">
                  <div className="contact-form-title">{t('contactFormSentTitle')}</div>
                  <p className="contact-form-subtitle">{t('contactFormSentBody')}</p>
                </div>
              )}
            </>
          )}

        </div>
      </div>

      {/* Flip card modal — real business card design, click to flip */}
      <div
        className={`card-overlay ${cardOpen ? "open" : ""}`}
        onClick={() => setCardOpen(false)}
      >
        <div className="card-stage" onClick={(e) => e.stopPropagation()}>
          <button
            className="card-close"
            onClick={() => setCardOpen(false)}
            aria-label={t('close')}
          >
            ×
          </button>
          <div
            className="card-clip"
            onMouseMove={(e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              const x = ((e.clientX - rect.left) / rect.width) * 100;
              const y = ((e.clientY - rect.top) / rect.height) * 100;
              setCardShine({ x, y, active: true });
            }}
            onMouseLeave={() => setCardShine({ x: 50, y: 50, active: false })}
            style={{
              transform: `rotateX(${((50 - cardShine.y) / 7).toFixed(2)}deg) rotateY(${((cardShine.x - 50) / 7).toFixed(2)}deg)`,
            }}
          >
            <div
              className={`card-flip ${cardFlipped ? "flipped" : ""}`}
              onClick={() => setCardFlipped((f) => !f)}
              role="button"
              aria-label={t('flipCard')}
            >
              <div className="card-flip-inner">
                <div
                  className="card-face card-face-front"
                  style={{
                    backgroundImage: `${CARD_SHINE_GRADIENT}, url(${CARD_FRONT_IMG})`,
                    backgroundSize: "220% 220%, contain",
                    backgroundPosition: `${cardShine.active ? `${cardShine.x}% ${cardShine.y}%` : "-150% -150%"}, center`,
                  }}
                />
                <div
                  className="card-face card-face-back"
                  style={{
                    backgroundImage: `${CARD_SHINE_GRADIENT}, url(${CARD_BACK_IMG})`,
                    backgroundSize: "220% 220%, contain",
                    backgroundPosition: `${cardShine.active ? `${cardShine.x}% ${cardShine.y}%` : "-150% -150%"}, center`,
                  }}
                />
              </div>
            </div>
          </div>
          <div className="card-hint">
            {cardFlipped ? t('cardHintFront') : t('cardHintFlip')}
          </div>
        </div>
      </div>

      {/* Identity card modal — click the prop on the desk to enlarge */}
      <div
        className={`idcard-overlay ${idCardOpen ? "open" : ""}`}
        onClick={() => setIdCardOpen(false)}
      >
        <div
          className="idcard-stage"
          onClick={(e) => e.stopPropagation()}
          onMouseMove={(e) => {
            const rect = e.currentTarget.getBoundingClientRect();
            const x = ((e.clientX - rect.left) / rect.width) * 100;
            const y = ((e.clientY - rect.top) / rect.height) * 100;
            setIdCardShine({ x, y, active: true });
          }}
          onMouseLeave={() => setIdCardShine({ x: 50, y: 50, active: false })}
        >
          <button
            className="idcard-close"
            onClick={() => setIdCardOpen(false)}
            aria-label={t('close')}
          >
            ×
          </button>
          <div className="idcard-frame">
            <div
              className="idcard-tilt"
              style={{
                transform: `rotateX(${((50 - idCardShine.y) / 7).toFixed(2)}deg) rotateY(${((idCardShine.x - 50) / 7).toFixed(2)}deg)`,
              }}
            >
              <div
                className="idcard-face"
                style={{ backgroundImage: `url(${lang === 'es' ? IDCARD_PROP_IMG_ES : IDCARD_PROP_IMG})` }}
              >
                <div
                  className="idcard-shine"
                  style={{
                    opacity: idCardShine.active ? 1 : 0,
                    backgroundPosition: `${idCardShine.x}% ${idCardShine.y}%`,
                  }}
                />
              </div>
            </div>

            <div className="idcard-annot">
              <svg className="idcard-annot-svg" viewBox="0 0 1600 1021" preserveAspectRatio="none">
                {/* Me. -> portrait (dot sits right at the photo's left edge, never over it) */}
                <line className="idcard-annot-line" x1="-38" y1="330" x2="75" y2="330" />
                <circle className="idcard-annot-dot" cx="75" cy="330" r="7" />

                {/* blank portrait placeholder -> headshot (dot sits right at the photo's top edge) */}
                <line className="idcard-annot-line" x1="235" y1="-40" x2="255" y2="95" />
                <circle className="idcard-annot-dot" cx="255" cy="95" r="7" />

                {/* Basic info. -> dot stops in the blank margin just above the title, never crossing it */}
                <line className="idcard-annot-line" x1="870" y1="-60" x2="870" y2="55" />
                <circle className="idcard-annot-dot" cx="870" cy="55" r="7" />

                {/* logo duplicate -> real logo */}
                <line className="idcard-annot-line" x1="1650" y1="-82" x2="1420" y2="120" />
                <circle className="idcard-annot-dot" cx="1420" cy="120" r="7" />

                {/* Contact info. -> dot grazes the barcode's top edge only, never crossing into it */}
                <line className="idcard-annot-line" x1="45" y1="1025" x2="120" y2="865" />
                <circle className="idcard-annot-dot" cx="120" cy="865" r="7" />

                {/* Tools i work with. -> dot sits in the blank margin below the icon row, approached from below so the line never crosses the icons or the signature */}
                <line className="idcard-annot-line" x1="870" y1="1105" x2="870" y2="990" />
                <circle className="idcard-annot-dot" cx="870" cy="990" r="7" />

                {/* Pictures. -> dot sits right at the full-body photo's right edge, never over it */}
                <line className="idcard-annot-line" x1="1630" y1="700" x2="1400" y2="600" />
                <circle className="idcard-annot-dot" cx="1400" cy="600" r="7" />
              </svg>

              <p className="idcard-annot-bio" style={{ left: "-2%", top: "-34%" }}>
                <ScrambleText key={`idbio-${lang}`} text={t('idAnnotBio')} play={idCardOpen} speed={14} />
              </p>

              <div className="idcard-annot-blankbox" style={{ left: "9%", top: "-30%", width: "13.5%", height: "25.5%" }}>
                <div className="idcard-annot-stampimg" style={{ backgroundImage: `url(${HEADSHOT_STAMP_IMG})`, backgroundSize: "contain", backgroundPosition: "center" }} />
                <span className="idcard-annot-vert"><ScrambleText key={`idportrait-${lang}`} text={t('idAnnotPortrait')} play={idCardOpen} /></span>
              </div>

              <div className="idcard-annot-label" style={{ left: "-6%", top: "32.3%" }}><ScrambleText key={`idme-${lang}`} text={t('idAnnotMe')} play={idCardOpen} /></div>
              <div className="idcard-annot-label" style={{ left: "54.4%", top: "-9.4%" }}><ScrambleText key={`idbasic-${lang}`} text={t('idAnnotBasicInfo')} play={idCardOpen} delay={80} /></div>
              <div
                className="idcard-annot-logo"
                style={{
                  left: "108%",
                  top: "-15%",
                  backgroundImage: `url(${IDCARD_PROP_IMG})`,
                  backgroundSize: "720px auto",
                  backgroundPosition: "-607px -33px",
                }}
              />
              <div className="idcard-annot-label" style={{ left: "-7%", top: "104.5%" }}><ScrambleText key={`idcontact-${lang}`} text={t('idAnnotContactInfo')} play={idCardOpen} delay={160} /></div>
              <div className="idcard-annot-label" style={{ left: "54.4%", top: "112%" }}><ScrambleText key={`idtools-${lang}`} text={t('idAnnotTools')} play={idCardOpen} delay={240} /></div>
              <div className="idcard-annot-label" style={{ left: "112%", top: "68.6%" }}><ScrambleText key={`idpictures-${lang}`} text={t('idAnnotPictures')} play={idCardOpen} delay={320} /></div>
              <div className="idcard-annot-blankbox" style={{ left: "103%", top: "84%", width: "11.15%", height: "38.6%" }}>
                <div className="idcard-annot-stampimg" style={{ backgroundImage: `url(${FULLBODY_STAMP_IMG})`, backgroundSize: "contain", backgroundPosition: "center" }} />
                <span className="idcard-annot-vert"><ScrambleText key={`idfullbody-${lang}`} text={t('idAnnotFullBody')} play={idCardOpen} delay={400} /></span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Headphones + iPod music player modal */}
      <div
        className={`player-overlay ${playerOpen ? "open" : ""}`}
        onClick={() => setPlayerOpen(false)}
      >
        <div className="player-stage" onClick={(e) => e.stopPropagation()}>
          <button
            className="player-close"
            onClick={() => setPlayerOpen(false)}
            aria-label={t('close')}
          >
            &times;
          </button>

          <div className={`player-scene ${playerReveal ? "unwound" : ""}`}>
            <div className="player-photo">
              <img src={PLAYER_PHOTO_IMG} alt={t('ipodAlt')} />
              <div className="player-screen-glow" />
              <button
                className="player-hotspot"
                onClick={togglePlay}
                disabled={!currentTrack}
                aria-label={isPlaying ? t('pause') : t('play')}
              />
            </div>
          </div>

          <div className="player-hint">
            <div className="player-hint-line" />
            <button className="player-hint-label" onClick={togglePlay} disabled={!currentTrack}>
              {isPlaying ? t('tapToPause') : t('tapCenterToPlay')}
            </button>
            {isPlaying && currentTrack && (
              <div className="player-hint-track">
                {`${currentTrack.title} \u2014 ${currentTrack.artist}`}
              </div>
            )}
          </div>

          {currentTrack && (
            <audio
              ref={audioRef}
              src={currentTrack.src}
              preload="auto"
            />
          )}
        </div>
      </div>

      {/* Pantalla de entrada: un click desbloquea el audio */}
      <div
        className={`enter-gate ${entered ? "gone" : ""}`}
        role="button"
        tabIndex={entered ? -1 : 0}
        onClick={enterSite}
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); enterSite(); } }}
      >
        <div className="enter-pill">
          <span className="enter-dot" />
          {lang === "es" ? "Click para entrar" : "Click to enter"}
        </div>
      </div>

      {/* Ventana de bienvenida (se abre sola al entrar) */}
      <div className={`welcome-overlay ${welcomeOpen ? "open" : ""}`} onClick={() => setWelcomeOpen(false)}>
        <div className="welcome-window" onClick={(e) => e.stopPropagation()}>
          <div className="welcome-bar">
            <div className="usb-traffic">
              <button type="button" className="usb-dot usb-dot-red" onClick={() => setWelcomeOpen(false)} aria-label={t('close')} />
              <button type="button" className="usb-dot usb-dot-yellow" onClick={() => setWelcomeOpen(false)} aria-label={lang === "en" ? "Minimize" : "Minimizar"} />
              <span className="usb-dot usb-dot-green" aria-hidden="true" style={{ cursor: "default" }} />
            </div>
            <span className="welcome-nav" aria-hidden="true">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6"><path d="M19 12H5M11 6l-6 6 6 6" /></svg>
            </span>
            <span className="welcome-nav" aria-hidden="true">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6"><path d="M5 12h14M13 6l6 6-6 6" /></svg>
            </span>
            <div className="welcome-address">
              <span>{t('welcomeAddress')}</span>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6"><circle cx="11" cy="11" r="6.5" /><path d="M20 20l-4.2-4.2" /></svg>
            </div>
            <span className="welcome-dots" aria-hidden="true"><i /><i /><i /></span>
          </div>
          <div className="welcome-body">
            <div className="welcome-cols">
              <div className="welcome-main">
                <div className="welcome-title">
                  <TypeScramble
                    key={`wt-${lang}-${welcomeOpen}`}
                    text={t('welcomeTitle')}
                    play={welcomeOpen}
                    delay={650}
                    cps={22}
                    onDone={() => setWelcomeStep((x) => Math.max(x, 0))}
                  />
                </div>
                <div className="welcome-blocks">
                  {t('welcomeBlocks').map((b, i) => (
                    <div key={`${lang}-${i}`} className={`welcome-block ${b.k} ${welcomeStep >= i ? "on" : ""}`}>
                      <span className="welcome-block-text">
                        <TypeScramble
                          key={`wb-${lang}-${i}-${welcomeOpen}`}
                          text={b.text}
                          play={welcomeOpen && welcomeStep >= i}
                          delay={60}
                          cps={b.k === "lead" ? 40 : 105}
                          onDone={() => setWelcomeStep((x) => Math.max(x, i + 1))}
                        />
                      </span>
                    </div>
                  ))}
                </div>
                <button type="button" className={`welcome-ok ${welcomeStep >= t('welcomeBlocks').length ? "show" : ""}`} onClick={() => setWelcomeOpen(false)}>
                  {t('welcomeOk')}
                </button>
              </div>
              <img className="welcome-doll" src={WELCOME_DOLL_IMG} alt="" draggable={false} />
            </div>
          </div>
        </div>
      </div>

      {/* USB — portafolio de video */}
      <div
        className={`usb-overlay ${usbOpen ? "open" : ""}`}
        onClick={() => { setUsbOpen(false); setActiveVideo(null); }}
      >
        <div className={`usb-stage ${usbReveal ? "revealed" : ""} ${usbMax ? "maximized" : ""} ${usbMin ? "minimizing" : ""}`} onClick={(e) => e.stopPropagation()}>
          <div className="usb-sidebar">
            <div className="usb-traffic">
              <button
                type="button"
                className="usb-dot usb-dot-red"
                onClick={() => { setUsbOpen(false); setActiveVideo(null); }}
                aria-label={t('close')}
              />
              <button
                type="button"
                className="usb-dot usb-dot-yellow"
                onClick={() => {
                  setUsbMin(true);
                  setTimeout(() => { setUsbOpen(false); setActiveVideo(null); setUsbMin(false); }, 420);
                }}
                aria-label={lang === "en" ? "Minimize" : "Minimizar"}
              />
              <button
                type="button"
                className="usb-dot usb-dot-green"
                onClick={() => setUsbMax((m) => !m)}
                aria-label={lang === "en" ? "Zoom" : "Ampliar ventana"}
              />
            </div>
            <nav className="usb-nav">
              {USB_CATEGORIES.map((cat) => (
                <button
                  key={cat.key}
                  type="button"
                  className={`usb-nav-item ${usbCategory === cat.key ? "active" : ""}`}
                  onClick={() => { setUsbCategory(cat.key); setActiveVideo(null); setActiveFolder(null); setActiveMenuFolder(null); }}
                >
                  {cat.label[lang]}
                </button>
              ))}
            </nav>
          </div>

          <div className="usb-content">
            <div className="usb-content-header">
              {USB_CATEGORIES.find((c) => c.key === usbCategory)?.label[lang]}
            </div>
            <div className="usb-content-body" key={usbCategory}>
              {usbCategory === "video" ? (
                <>
                  {USB_BG_PHOTO && (
                    <img className="usb-photo" src={USB_BG_PHOTO} alt="" />
                  )}

                  {activeFolder === null ? (
                    <div className="usb-folders">
                      {VIDEO_FOLDERS.map((f) => {
                        const count = VIDEOS.filter((v) => v.folder === f.key).length;
                        return (
                          <button
                            key={f.key}
                            className="usb-folder"
                            onClick={() => setActiveFolder(f.key)}
                            aria-label={f.label[lang]}
                          >
                            <svg className="usb-folder-icon" viewBox="0 0 64 54" aria-hidden="true">
                              <path
                                d="M2 10c0-3.3 2.7-6 6-6h14.5c1.8 0 3.5.8 4.7 2.2l3 3.5c.6.7 1.5 1.1 2.4 1.1H56c3.3 0 6 2.7 6 6v29c0 3.3-2.7 6-6 6H8c-3.3 0-6-2.7-6-6V10z"
                                fill="#2a2925"
                              />
                            </svg>
                            <span className="usb-folder-label">{f.label[lang]}</span>
                            <span className="usb-folder-count">{count}</span>
                          </button>
                        );
                      })}
                    </div>
                  ) : (
                    <div className="usb-folder-view">
                      <button className="usb-folder-back" onClick={() => setActiveFolder(null)}>
                        {t('backToFolders')}
                      </button>

                      {(() => {
                        const folderVideos = VIDEOS
                          .map((v, i) => ({ ...v, _i: i }))
                          .filter((v) => v.folder === activeFolder);
                        return (
                          <HoverCardStack
                            items={folderVideos}
                            lang={lang}
                            onOpen={(i) => setActiveVideo(folderVideos[i]._i)}
                            emptyImageLabel=""
                          />
                        );
                      })()}

                      <div className="usb-gallery-hint">{t(IS_TOUCH ? 'hoverToBrowseTouch' : 'hoverToBrowse')}</div>
                    </div>
                  )}

                  <div className={`usb-video-stage ${activeVideo !== null ? "open" : ""}`}>
                    {activeVideo !== null && (
                      <>
                        <div className="usb-video-frame">
                          {VIDEOS[activeVideo].embed ? (
                            <iframe
                              key={VIDEOS[activeVideo].embed}
                              className="usb-video-iframe"
                              src={VIDEOS[activeVideo].embed}
                              title={VIDEOS[activeVideo].title[lang]}
                              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                              allowFullScreen
                            />
                          ) : VIDEOS[activeVideo].src ? (
                            <BlobVideo key={VIDEOS[activeVideo].src} src={VIDEOS[activeVideo].src} poster={VIDEOS[activeVideo].thumb} />
                          ) : (
                            <div className="usb-video-placeholder">
                              {lang === "en"
                                ? `sample video — replace the "src" field of "${VIDEOS[activeVideo].title.en}" with your file or link`
                                : `video de muestra — reemplaza el campo "src" de "${VIDEOS[activeVideo].title.es}" con tu archivo o enlace`}
                            </div>
                          )}
                        </div>
                        <div className="usb-video-title">{VIDEOS[activeVideo].title[lang]}</div>
                        <button className="usb-video-back" onClick={() => setActiveVideo(null)}>
                          {t('backToGallery')}
                        </button>
                      </>
                    )}
                  </div>
                </>
              ) : usbCategory === "branding" ? (
                <div className="ig-grid">
                  {BRANDING_BOARDS.map((board, i) => (
                    <div className="board-card" key={board.title.en} style={{ transitionDelay: `${i * 70}ms` }}>
                      <div className="board-card-image">
                        <img src={board.img} alt="" />
                      </div>
                      <div className="board-card-label">{board.title[lang]}</div>
                    </div>
                  ))}
                </div>
              ) : usbCategory === "digital-art" ? (
                <div className="ig-grid">
                  {DIGITALART_ITEMS.map((item, i) => (
                    <div className="atm-card" key={item.title.en} style={{ transitionDelay: `${i * 70}ms` }}>
                      <img src={item.img} alt="" />
                      <div className="atm-card-label">{item.title[lang]}</div>
                    </div>
                  ))}
                </div>
              ) : usbCategory === "menudesign" ? (
                <div className="menu-scenes">
                  {MENU_BOOKS.map((book, i) => (
                    <MenuScene key={book.key} book={book} lang={lang} showCue={i < MENU_BOOKS.length - 1} />
                  ))}
                </div>
              ) : usbCategory === "social" ? (
                <div className="ig-grid">
                  {SOCIAL_POSTS.map((post, i) => (
                    <div className="ig-card" key={`${post.handle}-${i}`} style={{ transitionDelay: `${i * 70}ms` }}>
                      <div className="ig-card-header">
                        <div className="ig-avatar" style={{ background: post.avatarBg }}>
                          {post.handle.charAt(0).toUpperCase()}
                        </div>
                        <div className="ig-handle-col">
                          <span className="ig-handle">{post.handle}</span>
                        </div>
                        <span className="ig-dots">•••</span>
                      </div>
                      <div className="ig-image">
                        <img src={post.img} alt="" />
                      </div>
                      <div className="ig-actions">
                        <svg className="ig-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                          <path d="M12 20.3s-7.5-4.6-10-9.1C.5 7.8 2 4.2 5.4 3.4c2.1-.5 4.2.4 5.3 2.2l1.3 2 1.3-2c1.1-1.8 3.2-2.7 5.3-2.2 3.4.8 4.9 4.4 3.4 7.8-2.5 4.5-10 9.1-10 9.1Z"/>
                        </svg>
                        <svg className="ig-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                          <path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5 8.7 8.7 0 0 1-3.4-.7L3 21l1.8-5A8.5 8.5 0 1 1 21 11.5Z"/>
                        </svg>
                        <svg className="ig-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                          <path d="m3 11 18-8-8 18-2.5-7.5L3 11Z"/>
                        </svg>
                        <svg className="ig-icon ig-icon-bookmark" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
                          <path d="M6 3h12v18l-6-4-6 4V3Z"/>
                        </svg>
                      </div>
                      <div className="ig-likes">{post.likes} {lang === "en" ? "likes" : "Me gusta"}</div>
                      <div className="ig-caption">
                        <span className="ig-handle">{post.handle}</span> {post.caption[lang]}
                      </div>
                      <div className="ig-date">{post.date[lang]}</div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="usb-empty-category">
                  <div className="usb-empty-icon" />
                  <div className="usb-empty-text">
                    {lang === "en"
                      ? `add your ${USB_CATEGORIES.find((c) => c.key === usbCategory)?.label[lang]} projects here`
                      : `agrega aquí tus proyectos de ${USB_CATEGORIES.find((c) => c.key === usbCategory)?.label[lang]}`}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Papeles — proyecto grande con mazo de hojas detrás */}
      <div
        className={`papers-overlay ${papersOpen ? "open" : ""}`}
        onClick={() => setPapersOpen(false)}
      >
        <div className={`papers-stage ${papersReveal ? "revealed" : ""}`} onClick={(e) => e.stopPropagation()}>
          <button
            type="button"
            className="papers-close"
            onClick={() => setPapersOpen(false)}
            aria-label={t('close')}
          >
            ×
          </button>

          <div className="papers-deck" onClick={advanceDeck}>
            {ALL_PROJECTS.map((p, i) => {
              const pos = deckOrder.indexOf(i);
              const dir = pos % 2 === 0 ? -1 : 1;
              const rotate = pos === 0 ? -1.2 : dir * (2.4 + pos * 1.6);
              const tx = pos * 13;
              const ty = pos * -13;
              const scale = Math.max(1 - pos * 0.045, 0.82);
              const opacity = pos < 5 ? Math.max(1 - pos * 0.16, 0) : 0;
              return (
                <div
                  className={`paper-card paper-card-deck ${pos === 0 ? "is-front" : ""} ${p.pageImage ? "has-page-image" : ""}`}
                  key={p.code}
                  style={{
                    transform: `translate(${tx}px, ${ty}px) rotate(${rotate}deg) scale(${scale})`,
                    opacity,
                    zIndex: ALL_PROJECTS.length - pos,
                    pointerEvents: pos === 0 && papersOpen ? "auto" : "none",
                  }}
                >
                  {p.pageImage ? (
                    <div className="paper-card-deck-page-wrap">
                      <img className="paper-card-deck-page-img" src={p.pageImage} alt={p.title ? p.title[lang] : ""} />
                      {p.caption ? (
                        <div className="paper-overlay-caption">{p.caption[lang]}</div>
                      ) : null}
                      <div className="paper-overlay-body" style={p.overlayBodyTop ? { top: p.overlayBodyTop } : undefined}>
                        {p.nameLabel ? (
                          <p className="paper-overlay-row">
                            <span className="paper-overlay-label">{p.nameLabel[lang]}:</span>{" "}
                            {p.nameValue ? p.nameValue[lang] : (p.title ? p.title[lang] : "")}
                          </p>
                        ) : null}
                        {p.publishedDate ? (
                          <p className="paper-overlay-row">
                            <span className="paper-overlay-label">{t('publishedLabel')}:</span>{" "}
                            <span className="paper-overlay-date">{p.publishedDate}</span>
                          </p>
                        ) : null}
                        {p.description ? (
                          <p className="paper-overlay-desc">{p.description[lang]}</p>
                        ) : null}
                        {p.result ? (
                          <p className="paper-overlay-desc">
                            <span className="paper-overlay-label">{t('resultLabel')}:</span>{" "}
                            {p.result[lang]}
                          </p>
                        ) : null}
                        {p.morePhotos && p.morePhotos.length ? (
                          <p
                            className="paper-overlay-more"
                            onClick={(e) => { e.stopPropagation(); setMoreProject(p); }}
                          >
                            {t('seeMorePhotos')}
                          </p>
                        ) : null}
                      </div>
                    </div>
                  ) : (
                    <div className="paper-card-deck-wip">
                      <div className="paper-card-deck-wip-text">{t('inProgress')}</div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          {ALL_PROJECTS.length > 1 ? (
            <div className="papers-deck-hint">{t('deckHint')}</div>
          ) : null}
        </div>
      </div>

      {/* Lightbox de "más fotos" para los proyectos del mazo de hojas */}
      <div
        className={`morephotos-overlay ${moreProject ? "open" : ""}`}
        onClick={() => setMoreProject(null)}
      >
        <div className="morephotos-stage" onClick={(e) => e.stopPropagation()}>
          <button
            type="button"
            className="morephotos-close"
            onClick={() => setMoreProject(null)}
            aria-label={t('close')}
          >
            ×
          </button>
          {moreProject ? (
            <>
              <div className="morephotos-title">
                {moreProject.nameValue ? moreProject.nameValue[lang] : (moreProject.title ? moreProject.title[lang] : "")}
              </div>
              <div className="morephotos-grid">
                {moreProject.morePhotos.map((src, i) => {
                  const rotations = [-4, 3, -3, 5, -5, 2];
                  const rot = rotations[i % rotations.length];
                  return (
                    <div
                      className={`morephotos-item ${moreProject.morePhotos.length === 1 ? "single" : ""}`}
                      key={i}
                      style={{ "--rot": `${rot}deg` }}
                    >
                      <img src={src} alt="" />
                    </div>
                  );
                })}
              </div>
            </>
          ) : null}
        </div>
      </div>
    </div>
  );
}
